export function jsonResponse(success: boolean, data?: any, errorCode?: string, status: number = 200): Response {
  return new Response(
    JSON.stringify(
      success
        ? { success: true, data }
        : { success: false, error: { code: errorCode || 'UNKNOWN', message: errorCode || 'error' } }
    ),
    { status, headers: { 'Content-Type': 'application/json' } }
  );
}
