// Telemetry Exporter: aggregates metrics for compliance/economy/performance
import type { Env } from '../types';
import { startSpan, endSpan } from './otel';

export interface TelemetrySnapshot {
  ts: number;
  giftsToday: number;
  payoutRequestsToday: number;
  consentWritesToday: number;
  avgApiLatencyMs?: number;
  p50LatencyMs?: number;
  p95LatencyMs?: number;
}

export async function exportTelemetry(env: Env): Promise<TelemetrySnapshot> {
  const span = startSpan('telemetry.export');
  try {
    const now = Date.now();
    const since = now - 24 * 3600 * 1000;
    const giftsRow = await env.DB.prepare('SELECT COUNT(*) as c FROM gift_events WHERE created_at > ?1').bind(since).first<{ c: number }>();
    const payoutRow = await env.DB.prepare('SELECT COUNT(*) as c FROM payment_events WHERE event_type = "payout_pending" AND created_at > ?1').bind(since).first<{ c: number }>();
    const consentRow = await env.DB.prepare('SELECT COUNT(*) as c FROM consent_log WHERE created_at > datetime(?1, "unixepoch", "subsec")').bind(since / 1000).first<{ c: number }>();
    // Latency samples table maybe exists; fallback
    let avgLatency: number | undefined;
    let p50: number | undefined;
    let p95: number | undefined;
    try {
      const lat = await env.DB.prepare('SELECT AVG(latency_ms) as avgLatency FROM latency_samples WHERE ts > ?1').bind(since).first<{ avgLatency: number }>();
      avgLatency = lat?.avgLatency;
      const dist = await env.DB.prepare('SELECT latency_ms FROM latency_samples WHERE ts > ?1 ORDER BY latency_ms').bind(since).all<{ latency_ms: number }>();
      const arr = dist.results?.map(r => r.latency_ms).filter(n => typeof n === 'number') || [];
      if (arr.length) {
        const idx50 = Math.floor(arr.length * 0.50);
        const idx95 = Math.floor(arr.length * 0.95);
        p50 = arr[idx50];
        p95 = arr[idx95];
      }
    } catch {}
    return {
      ts: now,
      giftsToday: giftsRow?.c || 0,
      payoutRequestsToday: payoutRow?.c || 0,
      consentWritesToday: consentRow?.c || 0,
      avgApiLatencyMs: avgLatency,
      p50LatencyMs: p50,
      p95LatencyMs: p95
    };
  } finally {
    await endSpan(env, span, 'telemetry');
  }
}

// Record single latency sample (creates table if missing)
export async function recordLatencySample(env: Env, path: string, latencyMs: number) {
  try {
    await env.DB.prepare('CREATE TABLE IF NOT EXISTS latency_samples (ts INTEGER, path TEXT, latency_ms INTEGER)').run();
    await env.DB.prepare('INSERT INTO latency_samples (ts, path, latency_ms) VALUES (?1, ?2, ?3)')
      .bind(Date.now(), path, latencyMs).run();
  } catch (e) {
    // Non-fatal
  }
}
