import type { Env } from '../types';

interface ConnectionMeta { ws: WebSocket; region: string; joinedAt: number; roomId: string; }
interface RegionLatencyHistogram { buckets: number[]; samples: number; sum: number; max: number; }
interface LatencySample { ts: number; ms: number; }

// Global ChatRoom Durable Object (acts as a unified Pub/Sub mesh across all logical rooms).
// Region affinity influences transport performance only; content distribution is GLOBAL and NEVER restricted by region.
export class ChatRoom implements DurableObject {
  private readonly connections: Set<ConnectionMeta> = new Set();
  private readonly regionCounts: Map<string, number> = new Map();
  private readonly latencyBuckets: Map<string, RegionLatencyHistogram> = new Map();
  private readonly latencySeries: Map<string, LatencySample[]> = new Map(); // time-series for predictive modeling
  private readonly bucketThresholds = [20, 50, 100, 200, 500]; // ms boundaries
  private readonly maxSeriesLength = 300; // cap per region
  private readonly predictiveWindow = 30; // samples window for trend calculation
  private readonly p95Threshold = 150; // ms
  private readonly connectionHotThreshold = 0.8; // 80% of total

  // State/env are provided by runtime; constructor not used.
  // Default constructor retained by runtime; explicit logic not required.
  // eslint-disable-next-line @typescript-eslint/no-useless-constructor
  constructor(_state: DurableObjectState, _env: Env) {}

  async fetch(request: Request): Promise<Response> {
    const url = new URL(request.url);
    if (url.pathname.endsWith('/stats')) {
      console.log('[obs.do.chat.stats]', JSON.stringify({ ts: Date.now(), path: url.pathname }));
      return this.statsResponse();
    }
    if (request.headers.get('Upgrade') !== 'websocket') {
      return new Response(JSON.stringify({ success:false, error:{ code:'EXPECTED_UPGRADE', message:'Expected websocket upgrade or /stats' } }), { status:400, headers:{'Content-Type':'application/json'} });
    }
    return this.handleUpgrade(request);
  }

  private handleUpgrade(request: Request): Response {
    // Simple per-connection rate guard using URL + CF IP
    // IP captured by upstream layer; DO focuses on room distribution and latency telemetry
    const pair = new WebSocketPair();
    const client = pair[0];
    const server = pair[1];
    server.accept();

    // Extract region and logical room id (last segment) for metadata; region used only for telemetry.
    // @ts-ignore cf available at runtime
    const region = (request as any).cf?.colo || 'global';
    const roomId = new URL(request.url).pathname.split('/').pop() || 'default';
    const meta: ConnectionMeta = { ws: server, region, roomId, joinedAt: Date.now() };
    this.connections.add(meta);
    console.log('[obs.do.chat.join]', JSON.stringify({ ts: Date.now(), room: roomId, region, total: this.connections.size }));
    this.regionCounts.set(region, (this.regionCounts.get(region) || 0) + 1);

    server.send(`welcome|connections=${this.connections.size}|region=${region}|room=${roomId}`);

    const handlePing = (serverWs: WebSocket, regionStr: string, clientTsRaw?: string) => {
      if (clientTsRaw) {
        const clientTs = Number.parseInt(clientTsRaw, 10);
        if (!Number.isNaN(clientTs)) {
          const upstreamLatency = Date.now() - clientTs;
          this.recordLatency(regionStr, upstreamLatency);
          try { serverWs.send(`ping|${clientTs}|${upstreamLatency}`); } catch {}
          return;
        }
      }
      try { serverWs.send('ping'); } catch {}
    };

    server.addEventListener('message', (evt: MessageEvent) => {
      const raw = String(evt.data || '').trim();
      if (!raw) return;
      // Basic flood protection: limit messages per connection per minute
      // Uses in-memory counters due to DO affinity; can be extended to KV if global limits are needed
      try {
        // @ts-ignore attach simple counter on ws instance
        const count = (server as any)._msgc || 0;
        if (count > 600) { // 600 msgs/min per connection
          try { server.send(JSON.stringify({ type:'error', code:'RATE_LIMIT_EXCEEDED', message:'Too many messages' })); } catch {}
          try { server.close(429, 'Too many messages'); } catch {}
          return;
        }
        // @ts-ignore increment and schedule decay via no-op TTL (handled externally if needed)
        (server as any)._msgc = count + 1;
      } catch {}
      if (raw.startsWith('ping')) { const parts = raw.split('|'); handlePing(server, region, parts[1]); return; }
      // Global broadcast (no region filtering). Do not log payload to avoid sensitive data in logs.
      const envelope = JSON.stringify({ payload: raw, ts: Date.now(), region, room: roomId, globalConnections: this.connections.size });
      console.log('[obs.do.chat.broadcast]', JSON.stringify({ ts: Date.now(), room: roomId, region, size: this.connections.size }));
      for (const c of this.connections) {
        try { c.ws.send(envelope); } catch { this.connections.delete(c); }
      }
    });

    server.addEventListener('close', () => {
      this.connections.delete(meta);
      this.regionCounts.set(region, Math.max(0, (this.regionCounts.get(region) || 1) - 1));
      console.log('[obs.do.chat.leave]', JSON.stringify({ ts: Date.now(), room: roomId, region, total: this.connections.size }));
    });

    return new Response(null, { status: 101, webSocket: client });
  }

  private recordLatency(region: string, ms: number) {
    let hist = this.latencyBuckets.get(region);
    if (!hist) {
      hist = { buckets: new Array(this.bucketThresholds.length + 1).fill(0), samples: 0, sum: 0, max: 0 };
      this.latencyBuckets.set(region, hist);
    }
    let idx = this.bucketThresholds.findIndex(t => ms < t);
    if (idx === -1) idx = this.bucketThresholds.length; // overflow bucket
    hist.buckets[idx]++;
    hist.samples++;
    hist.sum += ms;
    if (ms > hist.max) hist.max = ms;

    // Time-series storage
    let series = this.latencySeries.get(region);
    if (!series) { series = []; this.latencySeries.set(region, series); }
    series.push({ ts: Date.now(), ms });
    if (series.length > this.maxSeriesLength) series.splice(0, series.length - this.maxSeriesLength);
  }

  private computeP95(region: string): number {
    const series = this.latencySeries.get(region);
    if (!series || series.length === 0) return 0;
    const sorted = series.map(s => s.ms).sort((a,b)=>a-b);
    const idx = Math.floor(sorted.length * 0.95);
    return sorted[idx];
  }

  private buildSuggestions(): string[] {
    const total = this.connections.size;
    if (total === 0) return [];
    const suggestions: string[] = [];

    const pickTarget = (exclude: string): string | undefined => {
      for (const [r2, c2] of this.regionCounts.entries()) {
        if (r2 === exclude) continue;
        const p95Target = this.computeP95(r2);
        const share = c2 / total;
        if (p95Target < 80 && share < 0.2) return r2;
      }
      return undefined;
    };

    for (const [region, count] of this.regionCounts.entries()) {
      const pct = count / total;
      const hist = this.latencyBuckets.get(region);
      const avg = hist?.samples ? hist.sum / hist.samples : 0;
      const p95 = this.computeP95(region);
      const needsAction = (pct > 0.5 && avg > 100) || p95 > this.p95Threshold;
      if (!needsAction) continue;
      const target = pickTarget(region);
      const msg = target
        ? `Shift ~20% traffic from ${region} to ${target} (avg ${avg.toFixed(1)}ms, p95 ${p95}ms).`
        : `Scale out edge capacity for ${region} (avg ${avg.toFixed(1)}ms, p95 ${p95}ms, ${Math.round(pct*100)}% load).`;
      suggestions.push(msg);
    }
    return suggestions;
  }

  private predictiveHotspot(region: string): boolean {
    const series = this.latencySeries.get(region);
    if (!series || series.length < this.predictiveWindow * 2) return false;
    // Compare recent window vs previous window avg
    const recent = series.slice(-this.predictiveWindow);
    const prev = series.slice(-this.predictiveWindow*2, -this.predictiveWindow);
    const avgRecent = recent.reduce((a,b)=>a+b.ms,0)/recent.length;
    const avgPrev = prev.reduce((a,b)=>a+b.ms,0)/prev.length;
    const growth = avgRecent - avgPrev;
    // Predict if continuing trend would exceed p95 threshold soon
    const projectedP95 = this.computeP95(region) + growth; // simplistic projection
    return growth > 15 && projectedP95 > this.p95Threshold; // growth >15ms and projected p95 beyond threshold
  }

  private regionAlerts(region: string, totalConnections: number) {
    const count = this.regionCounts.get(region) || 0;
    const pct = totalConnections ? count / totalConnections : 0;
    const p95 = this.computeP95(region);
    const hotspot = p95 > this.p95Threshold || pct > this.connectionHotThreshold;
    const predictive = this.predictiveHotspot(region);

    const reasons: string[] = [];
    if (p95 > this.p95Threshold) reasons.push(`p95 ${p95}ms > ${this.p95Threshold}ms threshold`);
    if (pct > this.connectionHotThreshold) reasons.push(`connection share ${(pct*100).toFixed(1)}% > ${(this.connectionHotThreshold*100).toFixed(0)}% threshold`);
    if (predictive) reasons.push('trend suggests imminent hotspot (growth & projected p95)');

    const findCandidate = (): string | undefined => {
      for (const [r2] of this.regionCounts.entries()) {
        if (r2 === region) continue;
        const p95c = this.computeP95(r2);
        const pctc = totalConnections ? (this.regionCounts.get(r2)||0)/totalConnections : 0;
        if (p95c < 80 && pctc < 0.25) return r2;
      }
      return undefined;
    };

    let recommendation: string | undefined;
    if (hotspot || predictive) {
      const cand = findCandidate();
      recommendation = cand ? `shift 15-25% traffic to ${cand}` : 'provision additional edge capacity or enable autoscale';
    }

    return { hotspot, predictive, reasons, recommendation, p95 };
  }

  private async statsResponse(): Promise<Response> {
    const regions: any = {};
    const total = this.connections.size;
    for (const [region, count] of this.regionCounts.entries()) {
      const hist = this.latencyBuckets.get(region);
      const avg = hist?.samples ? hist.sum / hist.samples : 0;
      const max = hist?.max || 0;
      const buckets = hist ? hist.buckets : new Array(this.bucketThresholds.length + 1).fill(0);
      const p95 = this.computeP95(region);
      const alerts = this.regionAlerts(region, total);
      const series = (this.latencySeries.get(region)||[]).slice(-50); // return last 50 samples for inspection
      regions[region] = { connections: count, latency: { buckets, thresholds: this.bucketThresholds, avg, max, p95, samples: hist?.samples || 0 }, alerts, series };
    }
    const payload = { regions, totalConnections: total, suggestions: this.buildSuggestions(), generatedAt: Date.now() };
    return new Response(JSON.stringify({ success: true, data: payload }), { status: 200, headers: { 'Content-Type': 'application/json' } });
  }
}
