import type { Env } from '../types';
import { jsonResponse } from '../utils/response.utils';
import { startSpan, endSpan } from '../utils/otel';
import { validatePayoutRequest, detectPayoutFraud, logPayoutAttempt } from '../utils/payout_validation';
import { ensureMinimumAgeRegionAware } from '../utils/guard';
import { logRestrictedAccess } from '../utils/legal_telemetry';

// Create payout request with comprehensive validation and fraud detection
export async function requestPayout(request: Request, env: Env): Promise<Response> {
  const span = startSpan('payout.request');
  try {
    const body = await request.json().catch(() => ({})) as any;
    const userId = body.userId;
    const amountCents = body.amountCents || body.amount; // Support both field names
    
    if (!userId || !amountCents || amountCents <= 0) {
      return jsonResponse(false, null, 'INVALID_PAYOUT', 400);
    }
    
    // Region-aware age gating for payouts (18+ minimum for financial transactions)
    const ageCheck = await ensureMinimumAgeRegionAware(env, userId, { ip: request.headers.get('cf-connecting-ip') || undefined });
    if (!ageCheck.allowed || ageCheck.requiredAge < 18) {
      await logRestrictedAccess(env, userId, 'payout_request', ageCheck.region, ageCheck.requiredAge, request);
      return jsonResponse(false, null, 'AGE_RESTRICTED_PAYOUT', 403);
    }
    
    // Validate payout request
    const validation = await validatePayoutRequest(env, userId, amountCents);
    
    if (!validation.allowed) {
      return jsonResponse(false, { 
        reason: validation.reason,
        balance: validation.balance,
        minimumBalance: validation.minimumBalance,
        dailyLimit: validation.dailyLimit,
        remainingDaily: validation.remainingDaily,
      }, validation.reason || 'VALIDATION_FAILED', 400);
    }
    
    // Run fraud detection
    const fraudCheck = await detectPayoutFraud(env, userId, amountCents);
    
    // Log attempt for audit trail
    await logPayoutAttempt(env, userId, amountCents, validation, fraudCheck);
    
    // If suspicious, flag for manual review
    const status = fraudCheck.suspicious ? 'review' : 'pending';
    
    const id = crypto.randomUUID();
    await env.DB.prepare(
      'INSERT INTO payment_events (id, user_id, event_type, amount_cents, status, metadata, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)'
    ).bind(
      id,
      userId,
      'payout_pending',
      amountCents,
      status,
      JSON.stringify({ fraudReasons: fraudCheck.reasons }),
      Date.now()
    ).run();
    
    return jsonResponse(true, { 
      id, 
      status,
      suspicious: fraudCheck.suspicious,
      reasons: fraudCheck.reasons,
      balance: validation.balance,
      remainingDaily: validation.remainingDaily,
    });
  } catch (e: any) {
    console.error('Payout request error:', e);
    return jsonResponse(false, null, 'PAYOUT_ERROR', 500);
  } finally {
    await endSpan(env, span, 'payout.request');
  }
}

// List payout ledger for user
export async function getLedger(request: Request, env: Env): Promise<Response> {
  const span = startSpan('payout.ledger');
  try {
    const url = new URL(request.url);
    const userId = url.pathname.split('/')[3]; // /payouts/ledger/:userId
    if (!userId) return jsonResponse(false, null, 'MISSING_USER', 400);
    const rs = await env.DB.prepare('SELECT id, event_type, amount, status, created_at FROM payment_events WHERE user_id=?1 ORDER BY created_at DESC LIMIT 100').bind(userId).all();
    return jsonResponse(true, { events: rs.results || [] });
  } catch (_) {
    return jsonResponse(false, null, 'LEDGER_ERROR', 500);
  } finally {
    await endSpan(env, span, 'payout.ledger');
  }
}

// Submit basic KYC info (stores as payment_event hold record for audit)
export async function submitKyc(request: Request, env: Env): Promise<Response> {
  const span = startSpan('payout.kyc');
  try {
    const body = await request.json().catch(() => ({})) as any;
    const userId = body.userId;
    const country = body.country;
    if (!userId || !country) return jsonResponse(false, null, 'INVALID_KYC', 400);
    // Represent KYC submission as a payment_event of type 'hold'
    const id = crypto.randomUUID();
    await env.DB.prepare('INSERT INTO payment_events (id, user_id, event_type, amount, status) VALUES (?1, ?2, ?3, ?4, ?5)')
      .bind(id, userId, 'hold', 0, 'pending').run();
    return jsonResponse(true, { kycId: id, status: 'pending' });
  } catch (_) {
    return jsonResponse(false, null, 'KYC_ERROR', 500);
  } finally {
    await endSpan(env, span, 'payout.kyc');
  }
}
