// Enhanced Payout Validation & Fraud Detection for Creator Economy
// Implements balance checks, duplicate prevention, velocity limits, KYC requirements

import type { Env } from '../types';
import { startSpan, endSpan } from '../utils/otel';

export interface PayoutValidationResult {
  allowed: boolean;
  reason?: string;
  balance?: number;
  minimumBalance?: number;
  dailyLimit?: number;
  remainingDaily?: number;
}

// Minimum withdrawal amount (in cents)
const MIN_PAYOUT_CENTS = 2000; // $20
const MAX_DAILY_PAYOUT_CENTS = 1000000; // $10,000 per day per user
const COOLDOWN_PERIOD_MS = 86400000; // 24 hours between payouts

export async function validatePayoutRequest(
  env: Env,
  userId: string,
  amountCents: number
): Promise<PayoutValidationResult> {
  const span = startSpan('payout.validate', { userId, amountCents });
  try {
    // 1. Check minimum amount
    if (amountCents < MIN_PAYOUT_CENTS) {
      return {
        allowed: false,
        reason: 'BELOW_MINIMUM',
        minimumBalance: MIN_PAYOUT_CENTS,
      };
    }
    
    // 2. Check user balance from payment_events
    const balanceResult = await env.DB.prepare(
      `SELECT SUM(
        CASE 
          WHEN event_type = 'gift_received' THEN amount_cents 
          WHEN event_type = 'payout_completed' THEN -amount_cents
          ELSE 0 
        END
      ) as balance FROM payment_events WHERE user_id = ?`
    ).bind(userId).first<{ balance: number }>();
    
    const balance = balanceResult?.balance || 0;
    
    if (balance < amountCents) {
      return {
        allowed: false,
        reason: 'INSUFFICIENT_BALANCE',
        balance,
      };
    }
    
    // 3. Check for duplicate pending requests
    const pendingResult = await env.DB.prepare(
      `SELECT COUNT(*) as count FROM payment_events 
       WHERE user_id = ? AND event_type = 'payout_pending' AND created_at > ?`
    ).bind(userId, Date.now() - COOLDOWN_PERIOD_MS).first<{ count: number }>();
    
    if ((pendingResult?.count || 0) > 0) {
      return {
        allowed: false,
        reason: 'PENDING_PAYOUT_EXISTS',
      };
    }
    
    // 4. Check daily velocity limit
    const todayStart = new Date().setHours(0, 0, 0, 0);
    const dailyResult = await env.DB.prepare(
      `SELECT SUM(amount_cents) as daily_total FROM payment_events 
       WHERE user_id = ? AND event_type IN ('payout_pending', 'payout_completed') 
       AND created_at > ?`
    ).bind(userId, todayStart).first<{ daily_total: number }>();
    
    const dailyTotal = dailyResult?.daily_total || 0;
    const remainingDaily = MAX_DAILY_PAYOUT_CENTS - dailyTotal;
    
    if (amountCents > remainingDaily) {
      return {
        allowed: false,
        reason: 'DAILY_LIMIT_EXCEEDED',
        dailyLimit: MAX_DAILY_PAYOUT_CENTS,
        remainingDaily,
      };
    }
    
    // 5. Check KYC status
    const kycResult = await env.DB.prepare(
      `SELECT kyc_status FROM payment_events 
       WHERE user_id = ? AND event_type = 'kyc_submitted' 
       ORDER BY created_at DESC LIMIT 1`
    ).bind(userId).first<{ kyc_status: string }>();
    
    const kycStatus = kycResult?.kyc_status || 'not_submitted';
    
    if (kycStatus !== 'approved' && amountCents >= 10000) { // $100+ requires KYC
      return {
        allowed: false,
        reason: 'KYC_REQUIRED',
      };
    }
    
    // All checks passed
    return {
      allowed: true,
      balance,
      remainingDaily,
    };
  } finally {
    await endSpan(env, span, 'payout.validate');
  }
}

export async function detectPayoutFraud(
  env: Env,
  userId: string,
  amountCents: number
): Promise<{ suspicious: boolean; reasons: string[] }> {
  const span = startSpan('payout.fraudCheck', { userId, amountCents });
  const reasons: string[] = [];
  
  try {
    // 1. Check for rapid succession withdrawals (velocity fraud)
    const recentPayouts = await env.DB.prepare(
      `SELECT COUNT(*) as count, SUM(amount_cents) as total 
       FROM payment_events 
       WHERE user_id = ? AND event_type IN ('payout_pending', 'payout_completed') 
       AND created_at > ?`
    ).bind(userId, Date.now() - 3600000).first<{ count: number; total: number }>(); // Last hour
    
    if ((recentPayouts?.count || 0) >= 3) {
      reasons.push('RAPID_WITHDRAWAL_PATTERN');
    }
    
    // 2. Check for balance drain (trying to withdraw entire balance immediately)
    const balanceResult = await env.DB.prepare(
      `SELECT SUM(
        CASE 
          WHEN event_type = 'gift_received' THEN amount_cents 
          WHEN event_type = 'payout_completed' THEN -amount_cents
          ELSE 0 
        END
      ) as balance FROM payment_events WHERE user_id = ?`
    ).bind(userId).first<{ balance: number }>();
    
    const balance = balanceResult?.balance || 0;
    const withdrawalPercent = (amountCents / balance) * 100;
    
    if (withdrawalPercent >= 95) {
      reasons.push('FULL_BALANCE_DRAIN');
    }
    
    // 3. Check for suspicious gift patterns (sudden influx before withdrawal)
    const recentGifts = await env.DB.prepare(
      `SELECT COUNT(*) as count, SUM(amount_cents) as total 
       FROM payment_events 
       WHERE user_id = ? AND event_type = 'gift_received' 
       AND created_at > ?`
    ).bind(userId, Date.now() - 86400000).first<{ count: number; total: number }>(); // Last 24h
    
    const giftTotal = recentGifts?.total || 0;
    
    if (giftTotal >= amountCents * 0.9 && (recentGifts?.count || 0) <= 2) {
      reasons.push('SUSPICIOUS_GIFT_PATTERN'); // Large gifts from few users before withdrawal
    }
    
    // 4. Check for new account fraud (account < 7 days old attempting large withdrawal)
    const accountAge = await env.DB.prepare(
      `SELECT MIN(created_at) as first_activity 
       FROM payment_events WHERE user_id = ?`
    ).bind(userId).first<{ first_activity: number }>();
    
    const accountAgeMs = Date.now() - (accountAge?.first_activity || Date.now());
    const accountAgeDays = accountAgeMs / 86400000;
    
    if (accountAgeDays < 7 && amountCents >= 5000) { // New account + $50+ withdrawal
      reasons.push('NEW_ACCOUNT_LARGE_WITHDRAWAL');
    }
    
    return {
      suspicious: reasons.length > 0,
      reasons,
    };
  } finally {
    await endSpan(env, span, 'payout.fraudCheck');
  }
}

export async function logPayoutAttempt(
  env: Env,
  userId: string,
  amountCents: number,
  validationResult: PayoutValidationResult,
  fraudCheck: { suspicious: boolean; reasons: string[] }
): Promise<void> {
  try {
    await env.DB.prepare(
      `INSERT INTO payment_events 
       (user_id, event_type, amount_cents, metadata, created_at) 
       VALUES (?, ?, ?, ?, ?)`
    ).bind(
      userId,
      'payout_attempt',
      amountCents,
      JSON.stringify({ validationResult, fraudCheck }),
      Date.now()
    ).run();
  } catch (error) {
    console.error('Failed to log payout attempt:', error);
  }
}
