// Video Processing Pipeline for Spaktok
// GPU-accelerated transcoding, thumbnail generation, and analytics

import type { Env } from '../types';

interface VideoProcessingJob {
  videoId: string;
  userId: string;
  sourceUrl: string;
  originalSize: number;
  startTime: string;
  status: 'pending' | 'processing' | 'completed' | 'failed';
}

interface TranscodingProfile {
  quality: '360p' | '720p' | '1080p' | '4k';
  resolution: { width: number; height: number };
  bitrate: number;
  fps: number;
}

interface ThumbnailConfig {
  positions: number[]; // Percentage positions (0-100)
  sizes: Array<{ width: number; height: number; name: string }>;
}

export class VideoProcessingService {
  private readonly TRANSCODING_PROFILES: TranscodingProfile[] = [
    {
      quality: '360p',
      resolution: { width: 640, height: 360 },
      bitrate: 800_000,
      fps: 30,
    },
    {
      quality: '720p',
      resolution: { width: 1280, height: 720 },
      bitrate: 2_500_000,
      fps: 30,
    },
    {
      quality: '1080p',
      resolution: { width: 1920, height: 1080 },
      bitrate: 5_000_000,
      fps: 60,
    },
    {
      quality: '4k',
      resolution: { width: 3840, height: 2160 },
      bitrate: 20_000_000,
      fps: 60,
    },
  ];

  private readonly THUMBNAIL_CONFIG: ThumbnailConfig = {
    positions: [0, 25, 50, 75, 100],
    sizes: [
      { width: 320, height: 180, name: 'small' },
      { width: 640, height: 360, name: 'medium' },
      { width: 1280, height: 720, name: 'large' },
    ],
  };

  constructor(private readonly env: Env) {}

  /**
   * Start video processing pipeline
   * Returns immediately, processing happens asynchronously
   */
  async startProcessing(
    videoId: string,
    userId: string,
    sourceUrl: string,
    originalSize: number
  ): Promise<void> {
    const job: VideoProcessingJob = {
      videoId,
      userId,
      sourceUrl,
      originalSize,
      startTime: new Date().toISOString(),
      status: 'pending',
    };

    // Store job in KV for tracking
    await this.env.CACHE.put(
      `processing:${videoId}`,
      JSON.stringify(job),
      { expirationTtl: 3600 } // 1 hour
    );

    // Update database status
    await this.env.DB.prepare(
      'UPDATE videos SET processing_status = ?, updated_at = ? WHERE id = ?'
    ).bind('processing', new Date().toISOString(), videoId).run();

    // Trigger async processing (in production, this would be a Queue or Durable Object)
    // For now, we'll use waitUntil to process in background
    // In real production: await this.env.PROCESSING_QUEUE.send({ videoId, userId, sourceUrl });
  }

  /**
   * Process video with GPU transcoding
   * This is a placeholder - actual implementation would use:
   * - Cloudflare Stream API
   * - GPU Workers for transcoding
   * - ffmpeg with GPU acceleration
   */
  async transcodeVideo(videoId: string, sourceUrl: string): Promise<{
    variants: Array<{ quality: string; url: string; size: number }>;
    duration: number;
  }> {
    try {
      // In production with GPU Workers:
      // 1. Download source video from R2
      // 2. Use ffmpeg with NVIDIA CUDA or AMD VCE for GPU transcoding
      // 3. Transcode to multiple qualities in parallel
      // 4. Upload variants to R2
      // 5. Return manifest with all quality URLs

      // Placeholder implementation
      const variants = this.TRANSCODING_PROFILES.map(profile => ({
        quality: profile.quality,
        url: `${sourceUrl.replace('.mp4', '')}_${profile.quality}.mp4`,
        size: Math.floor(this.estimateSize(profile)),
      }));

      // Simulate GPU transcoding time: ~30 seconds for 60 second video
      // Real GPU transcoding is much faster (2-5x real-time)
      const duration = 60; // Extract from video metadata in production

      // Store variants in database
      await this.env.DB.prepare(
        `INSERT INTO video_variants (video_id, quality, url, size, created_at)
         VALUES ${variants.map(() => '(?, ?, ?, ?, ?)').join(', ')}`
      ).bind(
        ...variants.flatMap(v => [
          videoId,
          v.quality,
          v.url,
          v.size,
          new Date().toISOString(),
        ])
      ).run();

      return { variants, duration };
    } catch (error) {
      console.error('Transcoding error:', error);
      throw error;
    }
  }

  /**
   * Generate thumbnails at key positions
   */
  async generateThumbnails(videoId: string, _sourceUrl: string): Promise<{
    thumbnails: Array<{ position: number; url: string; size: string }>;
    selected: string;
  }> {
    try {
      const thumbnails: Array<{ position: number; url: string; size: string }> = [];

      // In production with GPU processing:
      // 1. Extract frames at specified positions
      // 2. Resize to multiple sizes
      // 3. Run AI to select best thumbnail (face detection, composition)
      // 4. Upload all to R2
      // 5. Return URLs

      for (const position of this.THUMBNAIL_CONFIG.positions) {
        for (const size of this.THUMBNAIL_CONFIG.sizes) {
          thumbnails.push({
            position,
            url: `https://cdn.spaktok.com/thumbnails/${videoId}/p${position}_${size.name}.jpg`,
            size: size.name,
          });
        }
      }

      // AI-selected best thumbnail (simulated)
      const selected = thumbnails.find(t => t.position === 25 && t.size === 'large')!.url;

      // Store in database
      await this.env.DB.prepare(
        'UPDATE videos SET thumbnail_url = ? WHERE id = ?'
      ).bind(selected, videoId).run();

      return { thumbnails, selected };
    } catch (error) {
      console.error('Thumbnail generation error:', error);
      throw error;
    }
  }

  /**
   * Extract video metadata
   */
  async extractMetadata(videoId: string, _sourceUrl: string): Promise<{
    duration: number;
    width: number;
    height: number;
    fps: number;
    codec: string;
    bitrate: number;
    size: number;
  }> {
    try {
      // In production: Use ffprobe or media info API
      // For now, return placeholder data

      const metadata = {
        duration: 60,
        width: 1080,
        height: 1920,
        fps: 60,
        codec: 'h264',
        bitrate: 5_000_000,
        size: 37_500_000, // ~37.5 MB for 60s
      };

      // Update database
      await this.env.DB.prepare(
        `UPDATE videos SET 
         duration = ?, width = ?, height = ?, 
         updated_at = ?
         WHERE id = ?`
      ).bind(
        metadata.duration,
        metadata.width,
        metadata.height,
        new Date().toISOString(),
        videoId
      ).run();

      return metadata;
    } catch (error) {
      console.error('Metadata extraction error:', error);
      throw error;
    }
  }

  /**
   * Complete processing pipeline
   */
  async completeProcessing(videoId: string): Promise<void> {
    try {
      // Get source URL
      const video = await this.env.DB.prepare(
        'SELECT video_url FROM videos WHERE id = ?'
      ).bind(videoId).first();

      if (!video) {
        throw new Error('Video not found');
      }

      const sourceUrl = video.video_url as string;

      // 1. Extract metadata
      const metadata = await this.extractMetadata(videoId, sourceUrl);

      // 2. Transcode to multiple qualities
      const { variants, duration } = await this.transcodeVideo(videoId, sourceUrl);

      // 3. Generate thumbnails
      const { thumbnails, selected } = await this.generateThumbnails(videoId, sourceUrl);

      // 4. Update video status
      await this.env.DB.prepare(
        `UPDATE videos SET 
         processing_status = ?,
         duration = ?,
         thumbnail_url = ?,
         updated_at = ?
         WHERE id = ?`
      ).bind(
        'completed',
        duration,
        selected,
        new Date().toISOString(),
        videoId
      ).run();

      // 5. Clear processing cache
      await this.env.CACHE.delete(`processing:${videoId}`);

      // 6. Log analytics
      await this.logProcessingComplete(videoId, metadata, variants.length, thumbnails.length);

    } catch (error) {
      console.error('Complete processing error:', error);
      await this.failProcessing(videoId, error);
    }
  }

  /**
   * Mark processing as failed
   */
  async failProcessing(videoId: string, error: any): Promise<void> {
    await this.env.DB.prepare(
      'UPDATE videos SET processing_status = ? WHERE id = ?'
    ).bind('failed', videoId).run();

    // Store error for debugging
    await this.env.CACHE.put(
      `processing:error:${videoId}`,
      JSON.stringify({ error: String(error), timestamp: new Date().toISOString() }),
      { expirationTtl: 86400 } // 24 hours
    );
  }

  /**
   * Get processing status
   */
  async getProcessingStatus(videoId: string): Promise<VideoProcessingJob | null> {
    const jobData = await this.env.CACHE.get(`processing:${videoId}`);
    return jobData ? JSON.parse(jobData) : null;
  }

  /**
   * Log processing analytics
   */
  private async logProcessingComplete(
    videoId: string,
    metadata: any,
    variantCount: number,
    thumbnailCount: number
  ): Promise<void> {
    await this.env.DB.prepare(
      `INSERT INTO video_processing_logs (
        video_id, duration, variants_created, thumbnails_created,
        original_size, processing_time, created_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?)`
    ).bind(
      videoId,
      metadata.duration,
      variantCount,
      thumbnailCount,
      metadata.size,
      0, // Calculate from start time
      new Date().toISOString()
    ).run();
  }

  /**
   * Estimate transcoded file size
   */
  private estimateSize(profile: TranscodingProfile): number {
    // Simple estimation: bitrate * duration
    // For 60 second video
    return (profile.bitrate * 60) / 8; // Convert bits to bytes
  }
}
