import type { Env, RouteHandler } from '../types';

export const proxyBackend: RouteHandler = async (request, env: Env, _ctx, params) => {
  const backendOrigin = (env.BACKEND_ORIGIN || 'http://localhost:5000').replace(/\/$/, '');
  const url = new URL(request.url);
  const path = url.pathname.replace(/^\/backend/, '') || '/';
  const targetPath = params?.path ? `/${params.path}` : path;
  const targetUrl = `${backendOrigin}${targetPath}`;

  const headers = new Headers(request.headers);
  headers.set('x-cf-proxy', 'backend');

  const proxyReq = new Request(targetUrl, {
    method: request.method,
    headers,
    body: request.method === 'GET' || request.method === 'HEAD' ? undefined : request.body,
  });

  const response = await fetch(proxyReq);
  const resHeaders = new Headers(response.headers);
  resHeaders.set('x-cf-proxy', 'backend');
  return new Response(response.body, { status: response.status, headers: resHeaders });
};