// Minimal OpenTelemetry-like instrumentation utility for Workers
// Provides span timing and simple latency sample recording into D1.
import type { Env } from '../types';

export interface SpanContext { name: string; start: number; tags?: Record<string,string|number>; }

export function startSpan(name: string, tags?: Record<string,string|number>): SpanContext {
  return { name, start: Date.now(), tags };
}

export async function endSpan(env: Env, span: SpanContext, endpoint?: string) {
  const duration = Date.now() - span.start;
  try {
    if (endpoint) {
      // Insert/update latency sample (simplified). In production aggregate p50/p95.
      await env.DB.prepare('INSERT INTO latency_samples (id, endpoint, p50, p95, ts) VALUES (?1, ?2, ?3, ?4, ?5)')
        .bind(crypto.randomUUID(), endpoint, duration, duration, Date.now()).run();
    }
  } catch (_) {
    // swallow errors
  }
}

export async function instrumentRequest(env: Env, endpoint: string, fn: () => Promise<Response>): Promise<Response> {
  const span = startSpan(endpoint);
  try {
    const res = await fn();
    return res;
  } finally {
    await endSpan(env, span, endpoint);
  }
}
