// Stable Chat Handler - Production Ready
// Simplified service initialization without constructor complexity

import type { RouteHandler } from '../types';
import { ApiResponse } from '../types';
import { requireAuth } from '../middleware';

// Helper function to create API responses
function jsonResponse<T>(data: ApiResponse<T>, status = 200): Response {
  return new Response(JSON.stringify(data), {
    status,
    headers: { 'Content-Type': 'application/json' },
  });
}

/**
 * Get conversations with real-time presence
 */
export const getConversations: RouteHandler = async (request, env, _ctx, _params) => {
  const authResult = await requireAuth(request, env);
  if (authResult instanceof Response) return authResult;
  
  const userId = authResult.userId;

  try {
    // Get conversations
    const conversations = await env.DB.prepare(
      `SELECT 
        c.id, c.user1_id, c.user2_id, c.last_message_content,
        c.last_message_at, c.unread_count, c.created_at,
        u1.username as user1_username, u1.avatar_url as user1_avatar,
        u2.username as user2_username, u2.avatar_url as user2_avatar
      FROM conversations c
      JOIN users u1 ON c.user1_id = u1.id
      JOIN users u2 ON c.user2_id = u2.id
      WHERE c.user1_id = ? OR c.user2_id = ?
      ORDER BY c.last_message_at DESC`
    ).bind(userId, userId).all();

    // Get presence for all participants
    type ConversationRow = { user1_id: string; user2_id: string; user1_username: string; user2_username: string; user1_avatar: string; user2_avatar: string; id: string; last_message_content: string; last_message_at: string; unread_count: number; created_at: string };
    const participantIds = (conversations.results as ConversationRow[]).flatMap((conv) => [
      conv.user1_id as string,
      conv.user2_id as string,
    ]);
    
    const presenceMap = new Map<string, {
      userId: string; status: string; lastSeen: string; isTyping: boolean;
    }>();
    await Promise.all(participantIds.map(async (id) => {
      const presenceData = await env.CACHE.get(`presence:${id}`);
      if (presenceData) {
        presenceMap.set(id, JSON.parse(presenceData));
      } else {
        presenceMap.set(id, {
          userId: id,
          status: 'offline',
          lastSeen: new Date().toISOString(),
          isTyping: false,
        });
      }
    }));

    // Enhance conversations with presence
    const enhancedConversations = (conversations.results as ConversationRow[]).map((conv) => {
      const otherUserId = conv.user1_id === userId ? conv.user2_id : conv.user1_id;
      const presence = presenceMap.get(otherUserId as string);
      
      return {
        ...conv,
        otherUser: {
          id: otherUserId,
          username: conv.user1_id === userId ? conv.user2_username : conv.user1_username,
          avatarUrl: conv.user1_id === userId ? conv.user2_avatar : conv.user1_avatar,
          presence,
        },
      };
    });

    return jsonResponse({
      success: true,
      data: { conversations: enhancedConversations },
    });
  } catch (error) {
    console.error('Error fetching conversations:', error);
    return jsonResponse({
      success: false,
      error: {
        code: 'INTERNAL_ERROR',
        message: 'Failed to fetch conversations',
      },
    }, 500);
  }
};

/**
 * Get messages with real-time read receipts
 */
export const getMessages: RouteHandler = async (request, env, ctx, params) => {
  const authResult = await requireAuth(request, env);
  if (authResult instanceof Response) return authResult;
  
  const userId = authResult.userId;
  const conversationId = params.id as string;
  
  const url = new URL(request.url);
  const limit = Math.min(Number.parseInt(url.searchParams.get('limit') || '50', 10), 100);
  const before = url.searchParams.get('before');

  try {
    // Verify user is part of conversation
    const conversation = await env.DB.prepare(
      'SELECT * FROM conversations WHERE id = ? AND (user1_id = ? OR user2_id = ?)'
    ).bind(conversationId, userId, userId).first();

    if (!conversation) {
      return jsonResponse({
        success: false,
        error: { code: 'NOT_FOUND', message: 'Conversation not found' },
      }, 404);
    }

    // Get messages
    let query = `
      SELECT m.*, u.username, u.avatar_url
      FROM messages m
      JOIN users u ON m.sender_id = u.id
      WHERE m.conversation_id = ?
    `;
    const bindings: unknown[] = [conversationId];

    if (before) {
      query += ' AND m.created_at < ?';
      bindings.push(before);
    }

    query += ' ORDER BY m.created_at DESC LIMIT ?';
    bindings.push(limit);

    const messages = await env.DB.prepare(query).bind(...bindings).all();

    // Mark messages as delivered if not already
    type MessageRow = { id: string; receiver_id: string; delivered_at?: string; read_at?: string; ghost_mode?: number };
    const undeliveredIds = (messages.results as MessageRow[])
      .filter((m) => m.receiver_id === userId && !m.delivered_at)
      .map((m) => m.id);
    
    if (undeliveredIds.length > 0) {
      const now = new Date().toISOString();
      await Promise.all(undeliveredIds.map(id =>
        env.DB.prepare(
          'UPDATE messages SET status = ?, delivered_at = ? WHERE id = ?'
        ).bind('delivered', now, id).run()
      ));
    }

    // Auto-mark as read for ghost messages
    const ghostMessages = (messages.results as MessageRow[]).filter(
      (m) => m.receiver_id === userId && m.ghost_mode && !m.read_at
    );
    
    if (ghostMessages.length > 0) {
      const now = new Date().toISOString();
      await Promise.all(ghostMessages.map(m =>
        env.DB.prepare(
          'UPDATE messages SET is_read = 1, read_at = ?, status = ? WHERE id = ?'
        ).bind(now, 'read', m.id).run()
      ));
    }

    // Track conversation activity
    await env.CACHE.put(
      `activity:${userId}:${conversationId}`,
      JSON.stringify({ status: 'open', openedAt: new Date().toISOString() }),
      { expirationTtl: 300 }
    );

    return jsonResponse({
      success: true,
      data: { 
        messages: messages.results.reverse(),
        hasMore: messages.results.length === limit,
      },
    });
  } catch (error) {
    console.error('Error fetching messages:', error);
    return jsonResponse({
      success: false,
      error: { code: 'INTERNAL_ERROR', message: 'Failed to fetch messages' },
    }, 500);
  }
};

/**
 * Send message with encryption support
 */
export const sendMessage: RouteHandler = async (request, env, ctx, params) => {
  interface SendMessageBody {
    conversationId?: string;
    receiverId?: string;
    content?: string;
    mediaUrl?: string;
    mediaType?: string;
    encryptionMetadata?: Record<string, unknown>;
    ghostMode?: boolean;
    deleteOnView?: boolean;
    sensitivityLevel?: 'low' | 'medium' | 'high' | 'critical';
  }
  const authResult = await requireAuth(request, env);
  if (authResult instanceof Response) return authResult;
  
  const userId = authResult.userId;

  try {
    const body = (await request.json().catch(() => ({}))) as Partial<SendMessageBody>;
    const { 
      conversationId, 
      receiverId, 
      content,
      mediaUrl,
      mediaType,
      encryptionMetadata,
      ghostMode = false,
      deleteOnView = false,
      sensitivityLevel = 'medium',
    } = body;

    // Validate input
    if (!content && !mediaUrl) {
      return jsonResponse({
        success: false,
        error: { code: 'BAD_REQUEST', message: 'Content or media required' },
      }, 400);
    }

    let finalConversationId = conversationId;

    // Create conversation if it doesn't exist
    if (!conversationId && receiverId) {
      const existing = await env.DB.prepare(
        `SELECT id FROM conversations 
         WHERE (user1_id = ? AND user2_id = ?) OR (user1_id = ? AND user2_id = ?)`
      ).bind(userId, receiverId, receiverId, userId).first();

      if (existing) {
        finalConversationId = existing.id as string;
      } else {
        const newConvId = crypto.randomUUID();
        await env.DB.prepare(
          `INSERT INTO conversations (id, user1_id, user2_id, created_at)
           VALUES (?, ?, ?, ?)`
        ).bind(newConvId, userId, receiverId, new Date().toISOString()).run();
        
        finalConversationId = newConvId;
      }
    }

    // Calculate expiration based on sensitivity
    let expiresAt: string | undefined;
    if (ghostMode) {
      const ttlBySensitivity: Record<'low'|'medium'|'high'|'critical', number> = {
        low: 1440,
        medium: 60,
        high: 5,
        critical: 1,
      };
      const expirationMinutes = ttlBySensitivity[sensitivityLevel] ?? 60;
      
      expiresAt = new Date(Date.now() + expirationMinutes * 60000).toISOString();
    }

    // Create message
    const messageId = crypto.randomUUID();
    const now = new Date().toISOString();

    await env.DB.prepare(
      `INSERT INTO messages (
        id, conversation_id, sender_id, receiver_id, content,
        media_url, media_type, status, created_at,
        ghost_mode, delete_on_view, sensitivity_level,
        encryption_metadata, expires_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(
      messageId, finalConversationId, userId, receiverId || null, content,
      mediaUrl || null, mediaType || null, 'sent', now,
      ghostMode ? 1 : 0, deleteOnView ? 1 : 0, sensitivityLevel,
      encryptionMetadata ? JSON.stringify(encryptionMetadata) : null,
      expiresAt || null
    ).run();

    // Update conversation
    await env.DB.prepare(
      `UPDATE conversations 
       SET last_message_content = ?, last_message_at = ?, unread_count = unread_count + 1
       WHERE id = ?`
    ).bind(content || '[Media]', now, finalConversationId).run();

    // Clear conversation cache
    await env.CACHE.delete(`conv:list:${userId}`);
    await env.CACHE.delete(`conv:list:${receiverId}`);

    return jsonResponse({
      success: true,
      data: {
        message: {
          id: messageId,
          conversationId: finalConversationId,
          senderId: userId,
          receiverId,
          content,
          mediaUrl,
          mediaType,
          status: 'sent',
          createdAt: now,
          ghostMode,
          expiresAt,
        },
      },
    }, 201);
  } catch (error) {
    console.error('Error sending message:', error);
    return jsonResponse({
      success: false,
      error: { code: 'INTERNAL_ERROR', message: 'Failed to send message' },
    }, 500);
  }
};

/**
 * Start typing indicator
 */
export const startTyping: RouteHandler = async (request, env, ctx, params) => {
  interface TypingBody { conversationId: string }
  const authResult = await requireAuth(request, env);
  if (authResult instanceof Response) return authResult;
  
  const userId = authResult.userId;

  try {
    const body = (await request.json()) as Partial<TypingBody>;
    const { conversationId } = body;

    const now = new Date();
    const expiresAt = new Date(now.getTime() + 5000); // 5 seconds

    const indicator = {
      conversationId,
      userId,
      startedAt: now.toISOString(),
      expiresAt: expiresAt.toISOString(),
    };

    await env.CACHE.put(
      `typing:${conversationId}:${userId}`,
      JSON.stringify(indicator),
      { expirationTtl: 5 }
    );

    return jsonResponse({ success: true, data: indicator });
  } catch (error) {
    console.error('Error starting typing:', error);
    return jsonResponse({
      success: false,
      error: { code: 'INTERNAL_ERROR', message: 'Failed to start typing' },
    }, 500);
  }
};

/**
 * Stop typing indicator
 */
export const stopTyping: RouteHandler = async (request, env, ctx, params) => {
  interface TypingBody { conversationId: string }
  const authResult = await requireAuth(request, env);
  if (authResult instanceof Response) return authResult;
  
  const userId = authResult.userId;

  try {
    const body = (await request.json()) as Partial<TypingBody>;
    const { conversationId } = body;

    await env.CACHE.delete(`typing:${conversationId}:${userId}`);

    return jsonResponse({ success: true, data: null });
  } catch (error) {
    console.error('Error stopping typing:', error);
    return jsonResponse({
      success: false,
      error: { code: 'INTERNAL_ERROR', message: 'Failed to stop typing' },
    }, 500);
  }
};

/**
 * Update user presence
 */
export const updatePresence: RouteHandler = async (request, env, ctx, params) => {
  interface PresenceBody { status: string; currentConversationId?: string }
  const authResult = await requireAuth(request, env);
  if (authResult instanceof Response) return authResult;
  
  const userId = authResult.userId;

  try {
    const body = (await request.json().catch(() => ({}))) as Partial<PresenceBody>;
    const { status, currentConversationId } = body;

    if (!status) {
      return jsonResponse({ success:false, error:{ code:'BAD_REQUEST', message:'Missing status' } }, 400);
    }
    const presence = {
      userId,
      status,
      lastSeen: new Date().toISOString(),
      isTyping: false,
      currentConversationId,
    };

    await env.CACHE.put(
      `presence:${userId}`,
      JSON.stringify(presence),
      { expirationTtl: 30 }
    );

    return jsonResponse({ success: true, data: presence });
  } catch (error) {
    console.error('Error updating presence:', error);
    return jsonResponse({
      success: false,
      error: { code: 'INTERNAL_ERROR', message: 'Failed to update presence' },
    }, 500);
  }
};

/**
 * Get user presence
 */
export const getPresence: RouteHandler = async (request, env, ctx, params) => {
  const authResult = await requireAuth(request, env);
  if (authResult instanceof Response) return authResult;
  
  const targetUserId = params.userId as string;

  try {
    const presenceData = await env.CACHE.get(`presence:${targetUserId}`);
    
    let presence;
    if (presenceData) {
      presence = JSON.parse(presenceData);
    } else {
      presence = {
        userId: targetUserId,
        status: 'offline',
        lastSeen: new Date().toISOString(),
        isTyping: false,
      };
    }

    return jsonResponse({ success: true, data: presence });
  } catch (error) {
    console.error('Error getting presence:', error);
    return jsonResponse({
      success: false,
      error: { code: 'INTERNAL_ERROR', message: 'Failed to get presence' },
    }, 500);
  }
};

/**
 * Delete message (with ghost mode support)
 */
export const deleteMessage: RouteHandler = async (request, env, ctx, params) => {
  const authResult = await requireAuth(request, env);
  if (authResult instanceof Response) return authResult;
  
  const userId = authResult.userId;
  const messageId = params.id as string;

  try {
    // Get message
    const message = await env.DB.prepare(
      'SELECT * FROM messages WHERE id = ? AND sender_id = ?'
    ).bind(messageId, userId).first();

    if (!message) {
      return jsonResponse({
        success: false,
        error: { code: 'NOT_FOUND', message: 'Message not found' },
      }, 404);
    }

    // Permanent deletion for ghost mode
    if (message.ghost_mode) {
      await env.DB.prepare('DELETE FROM messages WHERE id = ?').bind(messageId).run();
      
      // Delete from cache
      await env.CACHE.delete(`msg:${messageId}`);
      
      // TODO: Delete media from R2 if exists
    } else {
      // Soft delete for normal messages
      await env.DB.prepare(
        'UPDATE messages SET status = ?, deleted_at = ? WHERE id = ?'
      ).bind('deleted', new Date().toISOString(), messageId).run();
    }

    return jsonResponse({ success: true, data: null });
  } catch (error) {
    console.error('Error deleting message:', error);
    return jsonResponse({
      success: false,
      error: { code: 'INTERNAL_ERROR', message: 'Failed to delete message' },
    }, 500);
  }
};
