import type { Env } from '../types';
import { startSpan, endSpan } from './otel';

/**
 * Firebase Admin SDK utilities for Cloudflare Workers
 * Verifies Firebase ID tokens and integrates with Workers JWT system
 * Enables seamless authentication bridge between Firebase Auth and Workers
 */

interface FirebaseTokenPayload {
  aud: string; // audience (project ID)
  auth_time: number;
  user_id: string;
  sub: string;
  iat: number; // issued at
  exp: number; // expiration
  email?: string;
  email_verified?: boolean;
  firebase: {
    identities: Record<string, any>;
    sign_in_provider: string;
  };
}

interface VerifiedToken {
  userId: string;
  email?: string;
  emailVerified: boolean;
  provider: string;
}

// Cache for Firebase JWKS (public keys). Firebase rotates roughly daily; respect cache-control.
let publicKeysCache: { keys: Record<string, JsonWebKey>; expiresAt: number } | null = null;

/**
 * Fetch Firebase public keys for token verification
 * Keys are cached for performance (24 hour TTL)
 */
interface FirebaseJwk extends JsonWebKey { kid?: string }

async function getFirebasePublicKeys(_env: Env): Promise<Record<string, FirebaseJwk>> {
  const now = Date.now();
  
  // Return cached keys if still valid
  if (publicKeysCache && publicKeysCache.expiresAt > now) {
    return publicKeysCache.keys;
  }
  
  try {
    // Fetch JWKS from Google's public key endpoint (preferred for direct JWK consumption)
    const response = await fetch(
      'https://www.googleapis.com/service_accounts/v1/jwk/securetoken@system.gserviceaccount.com'
    );
    
    if (!response.ok) {
      throw new Error(`Failed to fetch Firebase public keys: ${response.status}`);
    }
    
    const jwks = await response.json() as { keys: FirebaseJwk[] };
    const keys: Record<string, FirebaseJwk> = {};
    for (const k of jwks.keys) {
      if (k.kid) keys[k.kid] = k;
    }
    
    // Cache keys for 24 hours (standard Firebase key rotation)
    const cacheControl = response.headers.get('cache-control');
    const maxAge = cacheControl?.match(/max-age=(\d+)/)?.[1];
    const ttl = maxAge ? parseInt(maxAge) * 1000 : 24 * 60 * 60 * 1000;
    
    publicKeysCache = {
      keys,
      expiresAt: now + ttl,
    };
    
    return keys;
  } catch (error) {
    console.error('Error fetching Firebase public keys:', error);
    throw error;
  }
}

/**
 * Verify Firebase ID token
 * Returns user information if token is valid, null otherwise
 */
export async function verifyFirebaseToken(
  idToken: string,
  env: Env
): Promise<VerifiedToken | null> {
  const span = startSpan('firebase.verifyToken');
  
  try {
    // Firebase ID tokens are JWTs with 3 parts: header.payload.signature
    const parts = idToken.split('.');
    if (parts.length !== 3) {
      console.error('Invalid Firebase token format');
      return null;
    }
    
    // Decode header to get key ID (kid)
    const headerStr = atob(parts[0].replace(/-/g, '+').replace(/_/g, '/'));
    const header = JSON.parse(headerStr);
    const kid = header.kid;
    
    if (!kid) {
      console.error('Firebase token missing kid');
      return null;
    }
    
    // Decode payload to check expiration and project ID
    const payloadStr = atob(parts[1].replace(/-/g, '+').replace(/_/g, '/'));
    const payload = JSON.parse(payloadStr) as FirebaseTokenPayload;
    
    // Verify expiration
    const now = Math.floor(Date.now() / 1000);
    if (payload.exp < now) {
      console.error('Firebase token expired');
      return null;
    }
    
    // Verify issued-at time (not in future)
    if (payload.iat > now + 60) {
      console.error('Firebase token issued in future');
      return null;
    }
    
    // Verify project ID (audience)
    if (env.FIREBASE_PROJECT_ID && payload.aud !== env.FIREBASE_PROJECT_ID) {
      console.error('Firebase token audience mismatch');
      return null;
    }
    
    // Get public keys for signature verification
    const publicKeys = await getFirebasePublicKeys(env);
    const publicKeyJwk = publicKeys[kid];
    
    if (!publicKeyJwk) {
      console.error(`Firebase public key not found for kid: ${kid}`);
      return null;
    }
    
    // Full RSA signature verification with Web Crypto API
    try {
      const cryptoKey = await crypto.subtle.importKey(
        'jwk',
        publicKeyJwk,
        { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' },
        false,
        ['verify']
      );
      
      // Prepare signature data
      const dataToVerify = new TextEncoder().encode(`${parts[0]}.${parts[1]}`);
      const signatureBytes = Uint8Array.from(atob(parts[2].replace(/-/g, '+').replace(/_/g, '/')), c => c.charCodeAt(0));
      
      // Verify signature
      const isValid = await crypto.subtle.verify(
        'RSASSA-PKCS1-v1_5',
        cryptoKey,
        signatureBytes,
        dataToVerify
      );
      
      if (!isValid) {
        console.error('Firebase token signature invalid');
        return null;
      }
    } catch (sigErr) {
      console.error('Firebase token signature verification failed:', sigErr);
      return null;
    }
    
    // Return verified user information
    return {
      userId: payload.user_id,
      email: payload.email,
      emailVerified: payload.email_verified || false,
      provider: payload.firebase.sign_in_provider,
    };
  } catch (error) {
    console.error('Error verifying Firebase token:', error);
    return null;
  } finally {
    await endSpan(env, span, 'firebase.verifyToken');
  }
}

/**
 * Get or create user in D1 database from Firebase token
 * Auto-creates user on first Firebase login
 */
export async function getOrCreateUserFromFirebase(
  env: Env,
  firebaseUser: VerifiedToken
): Promise<{ id: string; username: string; email: string } | null> {
  const span = startSpan('firebase.getOrCreateUser');
  
  try {
    // Check if user already exists
    const existingUser = await env.DB.prepare(
      'SELECT id, username, email FROM users WHERE firebase_uid = ?1'
    )
      .bind(firebaseUser.userId)
      .first();
    
    if (existingUser) {
      return existingUser as any;
    }
    
    // User doesn't exist, create new user
    const userId = crypto.randomUUID();
    const username = `user_${userId.substring(0, 8)}`;
    const email = firebaseUser.email || `${userId}@firebase.local`;
    const displayName = firebaseUser.email?.split('@')[0] || username;
    
    await env.DB.prepare(
      `INSERT INTO users (
        id, username, email, password_hash, display_name, 
        firebase_uid, email_verified, followers_count, following_count, 
        likes_count, is_verified, is_premium, created_at, updated_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, 0, 0, 0, 0, 0, ?, ?)`
    )
      .bind(
        userId,
        username,
        email,
        '', // No password for Firebase users
        displayName,
        firebaseUser.userId,
        firebaseUser.emailVerified ? 1 : 0,
        Date.now(),
        Date.now()
      )
      .run();
    
    console.log(`Created new user from Firebase: ${userId}`, {
      provider: firebaseUser.provider,
      email: firebaseUser.email,
    });
    
    return {
      id: userId,
      username,
      email,
    };
  } catch (error) {
    console.error('Error getting/creating user from Firebase:', error);
    return null;
  } finally {
    await endSpan(env, span, 'firebase.getOrCreateUser');
  }
}

/**
 * Extract Firebase token from Authorization header
 * Supports both "Bearer <token>" and raw token formats
 */
export function extractFirebaseToken(authHeader: string | null): string | null {
  if (!authHeader) {
    return null;
  }
  
  // Remove "Bearer " prefix if present
  if (authHeader.startsWith('Bearer ')) {
    return authHeader.substring(7);
  }
  
  return authHeader;
}
