// Ad System Handlers: Campaign Management & Analytics

import type { RouteHandler } from '../types';
import { AdsService } from '../services/ads.service';
import { requireAuth } from '../middleware';
import { ensureMinimumAgeRegionAware } from '../utils/guard';
import { logRestrictedAccess } from '../utils/legal_telemetry';

function jsonSuccess<T>(data: T, message = 'Success'): Response {
  return new Response(JSON.stringify({
    success: true,
    data,
    message,
  }), {
    status: 200,
    headers: { 'Content-Type': 'application/json' },
  });
}

function jsonError(message: string, code = 'INTERNAL_ERROR', status = 500): Response {
  return new Response(JSON.stringify({
    success: false,
    error: { code, message },
  }), {
    status,
    headers: { 'Content-Type': 'application/json' },
  });
}

/**
 * Get ads for user feed (AI-powered selection)
 */
export const getAdsForFeed: RouteHandler = async (request, env, _ctx, _params) => {
  const authResult = await requireAuth(request, env);
  if (authResult instanceof Response) return authResult;
  
  const userId = authResult.userId;

  try {
    // Region-aware age gating for ad serving
    const url = new URL(request.url);
    const ageCheck = await ensureMinimumAgeRegionAware(env, userId, { ip: request.headers.get('cf-connecting-ip') || undefined });
    if (!ageCheck.allowed) {
      await logRestrictedAccess(env, userId, 'ads', ageCheck.region, ageCheck.requiredAge, request);
      return jsonError('Age verification required for ad viewing', 'AGE_RESTRICTED', 403);
    }

    const scrollPosition = Number.parseInt(url.searchParams.get('position') || '0', 10);

    const adsService = new AdsService(env);

    // Get adaptive layout (grid vs fullscreen)
    const { format, ads } = await adsService.getAdaptiveAdLayout(userId, scrollPosition);

    return jsonSuccess({
      format,
      ads,
      count: ads.length,
    }, 'Ads retrieved successfully');
  } catch (error: any) {
    return jsonError(error.message);
  }
};

/**
 * Track ad impression
 */
interface TrackImpressionBody {
  creativeId: string;
  campaignId: string;
  placement?: string;
  format?: 'grid' | 'fullscreen';
  position?: number;
}
export const trackImpression: RouteHandler = async (request, env, _ctx, _params) => {
  const authResult = await requireAuth(request, env);
  if (authResult instanceof Response) return authResult;
  
  const userId = authResult.userId;

  try {
    const raw = await request.json().catch(() => null);
    const body: Partial<TrackImpressionBody> = raw && typeof raw === 'object' ? (raw as Partial<TrackImpressionBody>) : {};
    const { creativeId, campaignId, placement, format, position } = body;

    if (!creativeId || !campaignId) {
      return jsonError('Missing required fields', 'VALIDATION_ERROR', 400);
    }

    const adsService = new AdsService(env);
    await adsService.trackImpression({
      creativeId,
      campaignId,
      userId,
      placement: placement || 'feed',
      format: (format === 'fullscreen' ? 'fullscreen' : 'grid'),
      position: Number(position ?? 0),
    });
    console.log('[obs.ads.impression]', JSON.stringify({ ts: Date.now(), hasCreative: !!creativeId, hasCampaign: !!campaignId, format: (format === 'fullscreen' ? 'fullscreen' : 'grid'), position: Number(position ?? 0) }));

    return jsonSuccess(null, 'Impression tracked');
  } catch (error: any) {
    return jsonError(error.message);
  }
};

