/**
 * Upload ad creative
 */
interface UploadCreativeBody {
  campaignId: string;
  format: 'grid' | 'fullscreen';
  mediaUrl: string;
  mediaType?: string;
  headline: string;
  description?: string;
  callToAction: string;
  destinationUrl: string;
}
export const uploadCreative: RouteHandler = async (request, env, _ctx, _params) => {
  const authResult = await requireAuth(request, env);
  if (authResult instanceof Response) return authResult;
  
  const userId = authResult.userId;

  try {
    const raw = await request.json().catch(() => null);
    const body: Partial<UploadCreativeBody> = raw && typeof raw === 'object' ? (raw as Partial<UploadCreativeBody>) : {};
    const {
      campaignId,
      format,
      mediaUrl,
      mediaType,
      headline,
      description,
      callToAction,
      destinationUrl,
    } = body;

    // Validation
    if (!campaignId || !format || !mediaUrl || !headline || !callToAction || !destinationUrl) {
      return jsonError('Missing required fields', 'VALIDATION_ERROR', 400);
    }

    // Verify campaign ownership
    const campaign = await env.DB.prepare(
      `SELECT c.id FROM ad_campaigns c
       JOIN advertisers a ON c.advertiser_id = a.id
       WHERE c.id = ? AND a.user_id = ?`
    ).bind(campaignId, userId).first();

    if (!campaign) {
      return jsonError('Campaign not found or access denied', 'NOT_FOUND', 404);
    }

    const creativeId = crypto.randomUUID();
    const now = new Date().toISOString();

    await env.DB.prepare(
      `INSERT INTO ad_creatives (
        id, campaign_id, format, media_url, media_type,
        headline, description, call_to_action, destination_url,
        status, created_at, updated_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending', ?, ?)`
    ).bind(
      creativeId,
      campaignId,
      (format ?? 'grid'),
      mediaUrl,
      mediaType,
      headline,
      description || '',
      callToAction,
      destinationUrl,
      now,
      now
    ).run();

    return jsonSuccess(
      { creativeId },
      'Creative uploaded - pending approval'
    );
  } catch (error: any) {
    return jsonError(error.message);
  }
};

/**
 * Get advertiser dashboard stats
 */
export const getAdvertiserDashboard: RouteHandler = async (request, env, _ctx, _params) => {
  const authResult = await requireAuth(request, env);
  if (authResult instanceof Response) return authResult;
  
  const userId = authResult.userId;

  try {
    // Get advertiser
    const advertiser = await env.DB.prepare(
      'SELECT * FROM advertisers WHERE user_id = ?'
    ).bind(userId).first();

    if (!advertiser) {
      return jsonError('Advertiser account not found', 'NOT_FOUND', 404);
    }

    // Get campaign summary
    const campaigns = await env.DB.prepare(
      `SELECT 
         COUNT(*) as total_campaigns,
         SUM(CASE WHEN status = 'active' THEN 1 ELSE 0 END) as active_campaigns,
         SUM(impressions) as total_impressions,
         SUM(clicks) as total_clicks,
         SUM(budget_spent) as total_spent,
         SUM(budget_remaining) as total_remaining
       FROM ad_campaigns
       WHERE advertiser_id = ?`
    ).bind(advertiser.id).first();

    // Get recent campaigns
    const recentCampaigns = await env.DB.prepare(
      `SELECT id, name, status, budget_total, budget_spent,
              impressions, clicks, created_at
       FROM ad_campaigns
       WHERE advertiser_id = ?
       ORDER BY created_at DESC
       LIMIT 5`
    ).bind(advertiser.id).all();

    return jsonSuccess({
      advertiser: {
        id: advertiser.id,
        companyName: advertiser.company_name,
        status: advertiser.status,
        totalSpent: advertiser.total_spent,
        averageCTR: advertiser.average_ctr,
      },
      summary: campaigns,
      recentCampaigns: recentCampaigns.results,
    }, 'Dashboard data retrieved');
  } catch (error: any) {
    return jsonError(error.message);
  }
};
