import type { Env } from '../types';
import { jsonResponse } from '../utils/response.utils';
import { startSpan, endSpan } from '../utils/otel';
import { createCoinsService } from '../services/coins.service';

/**
 * Stripe Webhook Handler
 * Handles webhooks from Stripe for payment events (charges, transfers, payouts)
 * Validates webhook signatures for security
 * Updates payment status in D1 database
 */

// Stripe webhook signature verification
async function verifyStripeSignature(
  payload: string,
  signature: string,
  secret: string
): Promise<boolean> {
  try {
    const encoder = new TextEncoder();
    
    // Extract timestamp and signature from header
    const signatureParts = signature.split(',');
    let timestamp = '';
    let expectedSignature = '';
    
    for (const part of signatureParts) {
      const [key, value] = part.split('=');
      if (key === 't') timestamp = value;
      if (key === 'v1') expectedSignature = value;
    }
    
    if (!timestamp || !expectedSignature) {
      return false;
    }
    
    // Construct signed payload: timestamp.payload
    const signedPayload = `${timestamp}.${payload}`;
    const signedData = encoder.encode(signedPayload);
    
    // Import secret as CryptoKey
    const key = await crypto.subtle.importKey(
      'raw',
      encoder.encode(secret),
      { name: 'HMAC', hash: 'SHA-256' },
      false,
      ['sign']
    );
    
    // Generate signature
    const signatureBuffer = await crypto.subtle.sign('HMAC', key, signedData);
    const signatureArray = Array.from(new Uint8Array(signatureBuffer));
    const computedSignature = signatureArray
      .map(b => b.toString(16).padStart(2, '0'))
      .join('');
    
    // Timing-safe comparison (compare all bytes to prevent timing attacks)
    if (computedSignature.length !== expectedSignature.length) {
      return false;
    }
    
    let mismatch = 0;
    for (let i = 0; i < computedSignature.length; i++) {
      if (computedSignature[i] !== expectedSignature[i]) {
        mismatch++;
      }
    }
    
    return mismatch === 0;
  } catch (error) {
    console.error('Stripe signature verification failed:', error);
    return false;
  }
}

// Main webhook handler
export async function handleStripeWebhook(
  request: Request,
  env: Env
): Promise<Response> {
  const span = startSpan('stripe.webhook');
  
  try {
    // Get webhook secret from environment
    if (!env.STRIPE_WEBHOOK_SECRET) {
      console.error('STRIPE_WEBHOOK_SECRET not configured');
      return jsonResponse(false, null, 'WEBHOOK_NOT_CONFIGURED', 500);
    }
    
    // Get raw body for signature verification
    const payload = await request.text();
    const signature = request.headers.get('stripe-signature');
    
    if (!signature) {
      return jsonResponse(false, null, 'MISSING_SIGNATURE', 400);
    }
    
    // Verify webhook signature
    const isValid = await verifyStripeSignature(
      payload,
      signature,
      env.STRIPE_WEBHOOK_SECRET
    );
    
    if (!isValid) {
      console.error('Invalid Stripe webhook signature');
      return jsonResponse(false, null, 'INVALID_SIGNATURE', 401);
    }
    
    // Parse event
    const event = JSON.parse(payload);
    const eventType = event.type;
    const eventData = event.data.object;
    
    console.log(`Received Stripe webhook: ${eventType}`, {
      id: event.id,
      objectId: eventData.id,
    });
    
    // Handle different event types
    switch (eventType) {
      case 'charge.succeeded':
        await handleChargeSucceeded(env, eventData);
        break;
        
      case 'charge.failed':
        await handleChargeFailed(env, eventData);
        break;
        
      case 'transfer.created':
        await handleTransferCreated(env, eventData);
        break;
        
      case 'transfer.paid':
        await handleTransferPaid(env, eventData);
        break;
        
      case 'transfer.failed':
        await handleTransferFailed(env, eventData);
        break;
        
      case 'payout.paid':
        await handlePayoutPaid(env, eventData);
        break;
        
      case 'payout.failed':
        await handlePayoutFailed(env, eventData);
        break;
        
      default:
        console.log(`Unhandled event type: ${eventType}`);
    }
    
    // Return 200 to acknowledge receipt
    return new Response(JSON.stringify({ received: true }), {
      status: 200,
      headers: { 'Content-Type': 'application/json' },
    });
  } catch (error: any) {
    console.error('Stripe webhook error:', error);
    return jsonResponse(false, null, 'WEBHOOK_ERROR', 500);
  } finally {
    await endSpan(env, span, 'stripe.webhook');
  }
}

// Handle successful charge (user purchased coins/premium)
async function handleChargeSucceeded(env: Env, charge: any): Promise<void> {
  const userId = charge.metadata?.userId;
  const amountCents = charge.amount;
  const chargeId = charge.id;
  const productType = charge.metadata?.productType;
  const packageId = charge.metadata?.packageId;
  
  if (!userId) {
    console.error('Charge missing userId in metadata:', chargeId);
    return;
  }
  
  try {
    // Update payment event to completed
    await env.DB.prepare(
      `UPDATE payment_events 
       SET status = 'completed', 
           metadata = json_set(metadata, '$.stripeChargeId', ?2),
           updated_at = ?3
       WHERE user_id = ?1 
         AND event_type = 'purchase' 
         AND amount_cents = ?4
         AND status = 'pending'
       ORDER BY created_at DESC
       LIMIT 1`
    )
      .bind(userId, chargeId, Date.now(), amountCents)
      .run();
    
    // Handle coin purchases with CoinsService
    if (productType === 'coins') {
      const coinsService = createCoinsService(env);
      
      // Get package details
      const coinPackage = packageId ? coinsService.getPackageById(packageId) : null;
      
      // Calculate total coins (base + bonus)
      let totalCoins = 0;
      if (coinPackage) {
        totalCoins = coinPackage.coins + (coinPackage.bonusCoins || 0);
      } else {
        // Fallback: extract from metadata
        totalCoins = charge.metadata?.coins ? parseInt(charge.metadata.coins) : 0;
      }
      
      if (totalCoins > 0) {
        // Credit coins using CoinsService (atomic transaction with audit trail)
        await coinsService.creditCoins(
          userId,
          totalCoins,
          'purchase',
          {
            stripeChargeId: chargeId,
            packageId: packageId,
            amountCents: amountCents,
            bonusCoins: coinPackage?.bonusCoins || 0,
            purchaseDate: Date.now(),
          }
        );
        
        console.log(`✅ Charge succeeded for user ${userId}: ${totalCoins} coins credited`, {
          chargeId,
          packageId,
          amountCents,
          baseCoins: coinPackage?.coins || 0,
          bonusCoins: coinPackage?.bonusCoins || 0,
        });
      } else {
        console.error('❌ No coins to credit for charge:', chargeId);
      }
    }
    
    // Handle premium subscription purchases
    else if (productType === 'premium') {
      await env.DB.prepare(
        `UPDATE users 
         SET premium_status = 'active',
             premium_tier = ?1,
             premium_expires_at = ?2,
             updated_at = ?3
         WHERE id = ?4`
      )
        .bind(
          charge.metadata?.tier || 'vip',
          Date.now() + 30 * 24 * 60 * 60 * 1000, // 30 days
          Date.now(),
          userId
        )
        .run();
      
      console.log(`✅ Premium subscription activated for user ${userId}`, {
        chargeId,
        tier: charge.metadata?.tier || 'vip',
      });
    }
    
    // Unknown product type
    else {
      console.warn(`⚠️ Unknown product type: ${productType} for charge ${chargeId}`);
    }
    
  } catch (error) {
    console.error('❌ Error handling charge.succeeded:', error);
    // Re-throw to trigger Stripe retry
    throw error;
  }
}

// Handle failed charge
async function handleChargeFailed(env: Env, charge: any): Promise<void> {
  const userId = charge.metadata?.userId;
  const chargeId = charge.id;
  const failureCode = charge.failure_code;
  const failureMessage = charge.failure_message;
  
  if (!userId) {
    console.error('Failed charge missing userId:', chargeId);
    return;
  }
  
  try {
    await env.DB.prepare(
      `UPDATE payment_events 
       SET status = 'failed',
           metadata = json_set(
             metadata, 
             '$.stripeChargeId', ?2,
             '$.failureCode', ?3,
             '$.failureMessage', ?4
           ),
           updated_at = ?5
       WHERE user_id = ?1
         AND event_type = 'purchase'
         AND status = 'pending'
       ORDER BY created_at DESC
       LIMIT 1`
    )
      .bind(userId, chargeId, failureCode, failureMessage, Date.now())
      .run();
    
    console.log(`Charge failed for user ${userId}:`, {
      chargeId,
      failureCode,
      failureMessage,
    });
  } catch (error) {
    console.error('Error handling charge.failed:', error);
  }
}

// Handle transfer created (creator payout initiated)
async function handleTransferCreated(env: Env, transfer: any): Promise<void> {
  const userId = transfer.metadata?.userId;
  const transferId = transfer.id;
  const amountCents = transfer.amount;
  
  if (!userId) {
    console.error('Transfer missing userId:', transferId);
    return;
  }
  
  try {
    await env.DB.prepare(
      `UPDATE payment_events 
       SET status = 'processing',
           metadata = json_set(metadata, '$.stripeTransferId', ?2),
           updated_at = ?3
       WHERE user_id = ?1
         AND event_type = 'payout_pending'
         AND amount_cents = ?4
         AND status IN ('pending', 'review')
       ORDER BY created_at DESC
       LIMIT 1`
    )
      .bind(userId, transferId, Date.now(), amountCents)
      .run();
    
    console.log(`Transfer created for user ${userId}:`, {
      transferId,
      amountCents,
    });
  } catch (error) {
    console.error('Error handling transfer.created:', error);
  }
}

// Handle transfer paid (payout completed)
async function handleTransferPaid(env: Env, transfer: any): Promise<void> {
  const userId = transfer.metadata?.userId;
  const transferId = transfer.id;
  
  if (!userId) {
    console.error('Transfer paid missing userId:', transferId);
    return;
  }
  
  try {
    await env.DB.prepare(
      `UPDATE payment_events 
       SET status = 'completed',
           updated_at = ?2
       WHERE user_id = ?1
         AND metadata LIKE '%' || ?3 || '%'
         AND event_type = 'payout_pending'
       LIMIT 1`
    )
      .bind(userId, Date.now(), transferId)
      .run();
    
    console.log(`Transfer paid for user ${userId}:`, { transferId });
  } catch (error) {
    console.error('Error handling transfer.paid:', error);
  }
}

// Handle transfer failed
async function handleTransferFailed(env: Env, transfer: any): Promise<void> {
  const userId = transfer.metadata?.userId;
  const transferId = transfer.id;
  const failureCode = transfer.failure_code;
  const failureMessage = transfer.failure_message;
  
  if (!userId) {
    console.error('Transfer failed missing userId:', transferId);
    return;
  }
  
  try {
    // Update payment event to failed
    await env.DB.prepare(
      `UPDATE payment_events 
       SET status = 'failed',
           metadata = json_set(
             metadata,
             '$.failureCode', ?2,
             '$.failureMessage', ?3
           ),
           updated_at = ?4
       WHERE user_id = ?1
         AND metadata LIKE '%' || ?5 || '%'
         AND event_type = 'payout_pending'
       LIMIT 1`
    )
      .bind(userId, failureCode, failureMessage, Date.now(), transferId)
      .run();
    
    // Refund user's balance (return money to their account)
    const result = await env.DB.prepare(
      `SELECT amount_cents FROM payment_events 
       WHERE user_id = ?1 
         AND metadata LIKE '%' || ?2 || '%'
       LIMIT 1`
    )
      .bind(userId, transferId)
      .first();
    
    if (result && result.amount_cents) {
      await env.DB.prepare(
        `UPDATE users 
         SET balance_cents = balance_cents + ?1,
             updated_at = ?2
         WHERE id = ?3`
      )
        .bind(result.amount_cents, Date.now(), userId)
        .run();
    }
    
    console.log(`Transfer failed for user ${userId}:`, {
      transferId,
      failureCode,
      failureMessage,
    });
  } catch (error) {
    console.error('Error handling transfer.failed:', error);
  }
}

// Handle payout paid (final confirmation)
async function handlePayoutPaid(_env: Env, payout: any): Promise<void> {
  const payoutId = payout.id;
  const amountCents = payout.amount;
  
  try {
    // Log successful payout (may affect multiple users)
    console.log('Payout paid:', {
      payoutId,
      amountCents,
      arrivalDate: payout.arrival_date,
    });
    
    // Additional tracking can be added here if needed
  } catch (error) {
    console.error('Error handling payout.paid:', error);
  }
}

// Handle payout failed
async function handlePayoutFailed(_env: Env, payout: any): Promise<void> {
  const payoutId = payout.id;
  const failureCode = payout.failure_code;
  const failureMessage = payout.failure_message;
  
  try {
    console.error('Payout failed:', {
      payoutId,
      failureCode,
      failureMessage,
    });
    
    // Alert system administrators (could integrate with monitoring)
    // This is critical - payouts failing means users aren't getting paid
  } catch (error) {
    console.error('Error handling payout.failed:', error);
  }
}
