import type { Env } from '../types';
import { jsonResponse } from '../utils/response.utils';
import { logConsentChange, logDataErasure, logAgeVerification } from '../utils/legal_telemetry';

// NOTE: These handlers assume presence of D1 tables (not created here):
// consent_log(subject TEXT, scope TEXT, version TEXT, ts INTEGER, region TEXT)
// age_verification(userId TEXT PRIMARY KEY, ageClass TEXT, verified BOOLEAN, ts INTEGER)
// erase_requests(id TEXT PRIMARY KEY, userId TEXT, status TEXT, requestedAt INTEGER, completedAt INTEGER)

export async function recordConsent(request: Request, env: Env): Promise<Response> {
  const body = await request.json().catch(() => ({})) as any;
  const userId = body.userId; const scopes = body.scopes || []; const version = body.version || 'v1'; const region = body.region || 'global';
  if (!userId || !Array.isArray(scopes) || scopes.length === 0) {
    return jsonResponse(false, null, 'INVALID_CONSENT', 400);
  }
  try {
    for (const scope of scopes) {
      await env.DB.prepare('INSERT INTO consent_log (subject, scope, version, ts, region) VALUES (?1, ?2, ?3, ?4, ?5)')
        .bind(userId, scope, version, Date.now(), region).run();
      // Log for legal audit trail
      await logConsentChange(env, userId, scope, true, request);
    }
    return jsonResponse(true, { recorded: scopes.length });
  } catch (error_: any) {
    return jsonResponse(false, { reason: error_.message || 'ERROR' }, 'CONSENT_WRITE_FAILED', 500);
  }
}

export async function getConsent(_request: Request, env: Env, _ctx: ExecutionContext, _params: Record<string,string>): Promise<Response> {
  const userId = _params.userId;
  const result = await env.DB.prepare('SELECT scope, version, ts, region FROM consent_log WHERE subject = ?1').bind(userId).all();
  return jsonResponse(true, { entries: result.results });
}

export async function withdrawConsent(request: Request, env: Env, _ctx: ExecutionContext, params: Record<string,string>): Promise<Response> {
  const userId = params.userId;
  const body = await request.json().catch(() => ({})) as any;
  const scopes = body.scopes || [];
  if (!Array.isArray(scopes) || scopes.length === 0) return jsonResponse(false, null, 'INVALID_SCOPES', 400);
  try {
    for (const scope of scopes) {
      await env.DB.prepare('DELETE FROM consent_log WHERE subject = ?1 AND scope = ?2').bind(userId, scope).run();
      // Log consent withdrawal for legal audit
      await logConsentChange(env, userId, scope, false, request);
    }
    return jsonResponse(true, { removed: scopes.length });
  } catch (error_: any) {
    return jsonResponse(false, { reason: error_.message || 'ERROR' }, 'CONSENT_WITHDRAW_FAILED', 500);
  }
}

export async function eraseUserData(_request: Request, env: Env, _ctx: ExecutionContext, _params: Record<string,string>): Promise<Response> {
  const userId = _params.userId;
  const reqId = crypto.randomUUID();
  // Insert initial request (initiated)
  await env.DB.prepare('INSERT INTO erase_requests (id, user_id, status, initiated_at) VALUES (?1, ?2, ?3, ?4)')
    .bind(reqId, userId, 'processing', Date.now()).run();
  try {
    // Begin transaction for atomic grouping of erasure metadata updates
    await env.DB.prepare('BEGIN').run();
    try {
      // Delete consent records
      await env.DB.prepare('DELETE FROM consent_log WHERE subject = ?1').bind(userId).run();
      // Delete payment events
      await env.DB.prepare('DELETE FROM payment_events WHERE user_id = ?1').bind(userId).run();
      // Delete gift events (user as sender or receiver)
      await env.DB.prepare('DELETE FROM gift_events WHERE sender_id = ?1 OR receiver_id = ?1').bind(userId).run();
      // Delete referral data
      await env.DB.prepare('DELETE FROM referral_activations WHERE referred_user_id = ?1').bind(userId).run();
      await env.DB.prepare('DELETE FROM referral_codes WHERE owner_user_id = ?1').bind(userId).run();
      // Age verification record removal
      await env.DB.prepare('DELETE FROM age_verification WHERE user_id = ?1 OR userId = ?1').bind(userId).run();
      // Delete cached feed entries
      await env.DB.prepare('DELETE FROM feed_cache WHERE user_id = ?1').bind(userId).run().catch(()=>{});
      // Delete ads analytics tied to user
      await env.DB.prepare('DELETE FROM ad_impressions WHERE user_id = ?1').bind(userId).run().catch(()=>{});
      await env.DB.prepare('DELETE FROM ad_clicks WHERE user_id = ?1').bind(userId).run().catch(()=>{});
      // Delete messages/comments/videos authored by user
      await env.DB.prepare('DELETE FROM comments WHERE user_id = ?1').bind(userId).run().catch(()=>{});
      await env.DB.prepare('DELETE FROM messages WHERE sender_id = ?1 OR receiver_id = ?1').bind(userId).run().catch(()=>{});
      await env.DB.prepare('DELETE FROM videos WHERE user_id = ?1').bind(userId).run().catch(()=>{});
      await env.DB.prepare('COMMIT').run();
    } catch (error_) {
      await env.DB.prepare('ROLLBACK').run();
      throw error_;
    }
    // Mark request completed
    await env.DB.prepare('UPDATE erase_requests SET status = ?1, completed_at = ?2 WHERE id = ?3')
      .bind('completed', Date.now(), reqId).run();
    
    // Log erasure for legal compliance
    await logDataErasure(env, userId, ['consent', 'payments', 'gifts', 'referrals', 'age_verification', 'feed_cache', 'ads', 'comments', 'messages', 'videos'], 0);
    
    return jsonResponse(true, { status: 'completed', requestId: reqId });
  } catch (e: any) {
    await env.DB.prepare('UPDATE erase_requests SET status = ?1, failure_reason = ?2 WHERE id = ?3')
      .bind('failed', e.message || 'ERROR', reqId).run();
    return jsonResponse(false, null, 'COMPLIANCE_ERASE_FAILED', 500);
  }
}

export async function recordAgeVerification(request: Request, env: Env): Promise<Response> {
  const body = await request.json().catch(() => ({})) as any;
  const userId = body.userId; const ageClass = body.ageClass; const verified = !!body.verified;
  if (!userId || !ageClass) return jsonResponse(false, null, 'INVALID_AGE_DATA', 400);
  
  // Log age verification for legal audit
  await logAgeVerification(env, userId, ageClass, body.method || 'self-reported', request);
  try {
    await env.DB.prepare('INSERT OR REPLACE INTO age_verification (userId, ageClass, verified, ts) VALUES (?1, ?2, ?3, ?4)')
      .bind(userId, ageClass, verified ? 1 : 0, Date.now()).run();
    return jsonResponse(true, { userId, ageClass, verified });
  } catch (e: any) {
    // Attempt to auto-create table if missing then retry once
    const msg = String(e.message||'');
    if (/no such table/i.test(msg)) {
      try {
        await env.DB.prepare('CREATE TABLE IF NOT EXISTS age_verification (userId TEXT PRIMARY KEY, ageClass TEXT, verified INTEGER, ts INTEGER)').run();
        await env.DB.prepare('INSERT OR REPLACE INTO age_verification (userId, ageClass, verified, ts) VALUES (?1, ?2, ?3, ?4)')
          .bind(userId, ageClass, verified ? 1 : 0, Date.now()).run();
        return jsonResponse(true, { userId, ageClass, verified, autoCreated:true });
      } catch (error_:any) {
        return jsonResponse(false, { reason: error_.message||'ERROR' }, 'AGE_VERIFICATION_FAILED', 500);
      }
    }
    return jsonResponse(false, { reason: msg }, 'AGE_VERIFICATION_FAILED', 500);
  }
}

// Compliance audit endpoint: summarize user consent entries, age verification, erase requests, anomalies
export async function auditUserCompliance(_req: Request, env: Env, _ctx: ExecutionContext, params: Record<string,string>): Promise<Response> {
  const userId = params.userId;
  try {
    const consent = await env.DB.prepare('SELECT scope, version, ts, region FROM consent_log WHERE subject=?1 ORDER BY ts DESC LIMIT 100').bind(userId).all();
    const age = await env.DB.prepare('SELECT ageClass, verified, ts FROM age_verification WHERE user_id=?1 OR userId=?1').bind(userId).first();
    const erase = await env.DB.prepare('SELECT id, status, initiated_at, completed_at, failure_reason FROM erase_requests WHERE user_id=?1 ORDER BY initiated_at DESC LIMIT 20').bind(userId).all();
    const anomalies = await env.DB.prepare('SELECT COUNT(*) as cnt FROM gift_anomalies WHERE user_id=?1').bind(userId).first();
    const tax = await env.DB.prepare('SELECT country_code, tax_class, updated_at FROM user_tax_profile WHERE user_id=?1').bind(userId).first();
    const region = await env.DB.prepare('SELECT region_code, residency_version, updated_at FROM user_region_meta WHERE user_id=?1').bind(userId).first();
    return jsonResponse(true, {
      consent: consent.results || [],
      ageVerification: age || null,
      eraseRequests: erase.results || [],
      anomalyCount: anomalies?.cnt || 0,
      taxProfile: tax || null,
      regionProfile: region || null
    });
  } catch (error_:any) {
    return jsonResponse(false, { reason: error_.message || 'ERROR' }, 'AUDIT_FAILED', 500);
  }
}
