import type { RouteHandler } from '../types';

// Minimal in-memory room registry (single room optimization keeps structure for future scaling)
const rooms: Map<string, Set<WebSocket>> = new Map();
function getRoom(id: string): Set<WebSocket> {
  let r = rooms.get(id); if (!r) { r = new Set(); rooms.set(id, r); } return r;
}

export const handleChatWebSocket: RouteHandler = async (request, env, _ctx, params) => {
  try {
    if (request.headers.get('Upgrade') !== 'websocket') {
      return new Response('Expected websocket', { status: 400 });
    }

    // KV-backed rate limit guard (per IP + room)
    const ip = request.headers.get('CF-Connecting-IP') || 'unknown';
    const rlKey = `ws:ratelimit:${ip}:${params.roomId || 'latencyroom'}`;
    const currentStr = await env.RATE_LIMIT.get(rlKey);
    const current = currentStr ? Number.parseInt(currentStr, 10) : 0;
    if (current >= 60) { // cap at 60 upgrades per minute per IP+room
      return new Response(JSON.stringify({ success:false, error:{ code:'RATE_LIMIT_EXCEEDED', message:'Too many websocket upgrades. Try again later.' } }), { status:429, headers:{'Content-Type':'application/json'} });
    }
    await env.RATE_LIMIT.put(rlKey, String(current + 1), { expirationTtl: 60 });

    const roomId = params.roomId || 'latencyroom';
    const pair = new WebSocketPair();
    const client = pair[0];
    const server = pair[1];
    server.accept();
    const room = getRoom(roomId);

    // --- Payload constraints ---
    const MAX_MSG_BYTES = 2048; // cap incoming message size ~2KB
    const MAX_CHAT_LEN = 256;   // chat payload string length cap
    const PRESENCE_TTL = 60;    // seconds
    const TYPING_TTL = 5;       // seconds

    // Presence/Typing utilities (KV-based, consolidated TTL handling)
    const presenceKey = (uid: string, room: string) => `presence:${room}:${uid}`;
    const typingKey = (uid: string, room: string) => `typing:${room}:${uid}`;
    const setPresence = async (uid?: string) => {
      if (!uid) return;
      await env.RATE_LIMIT.put(presenceKey(uid, roomId), String(Date.now()), { expirationTtl: PRESENCE_TTL });
      if (env.ANALYTICS) {
        env.ANALYTICS.writeDataPoint({ blobs: ['presence_update', roomId], doubles: [1], indexes: [env.ENVIRONMENT] });
      }
    };
    const setTyping = async (uid?: string) => {
      if (!uid) return;
      await env.RATE_LIMIT.put(typingKey(uid, roomId), String(Date.now()), { expirationTtl: TYPING_TTL });
      if (env.ANALYTICS) {
        env.ANALYTICS.writeDataPoint({ blobs: ['typing_update', roomId], doubles: [1], indexes: [env.ENVIRONMENT] });
      }
    };
    const clearPresence = async (uid?: string) => {
      if (!uid) return;
      await env.RATE_LIMIT.delete(presenceKey(uid, roomId));
    };
    const clearTyping = async (uid?: string) => {
      if (!uid) return;
      await env.RATE_LIMIT.delete(typingKey(uid, roomId));
    };

    // --- Auth state ---
    let authed = false;
    let userContext: { userId?: string; role?: string; twofa?: boolean } = {};

    // Helper: send error and close
    function sendError(code: number, message: string) {
      server.send(JSON.stringify({ type: 'error', code, message }));
      try { server.close(code, message); } catch {}
    }

    // First message must be auth
    const handleRateLimit = async (ipAddr: string, roomKey: string) => {
      const msgKey = `ws:msg:${ipAddr}:${roomKey}`;
      const msgStr = await env.RATE_LIMIT.get(msgKey);
      const msgCount = msgStr ? Number.parseInt(msgStr, 10) : 0;
      if (msgCount > 300) { // 300 messages/min per IP+room
        sendError(429, 'Message rate exceeded');
        return false;
      }
      await env.RATE_LIMIT.put(msgKey, String(msgCount + 1), { expirationTtl: 60 });
      return true;
    };

    const isValidRole = (role: string) => /^ROLE_(ADMIN|OPS|USER)$/.test(role);
    const isOversized = (data: any) => {
      try {
        const size = typeof data === 'string' ? new TextEncoder().encode(data).byteLength : (data as ArrayBuffer)?.byteLength ?? 0;
        return size > MAX_MSG_BYTES;
      } catch { return false; }
    };

    const parseJSON = <T>(raw: string): T | null => { try { return JSON.parse(raw) as T; } catch { return null; } };

    const validateAuth = (raw: string) => {
      const auth = parseJSON<{ token?: string; role?: string; twofa?: boolean }>(raw);
      if (!auth) return { ok:false, code:400, msg:'Malformed auth payload' } as const;
      if (!auth.token || typeof auth.token !== 'string' || auth.token.length > 512) return { ok:false, code:401, msg:'Invalid token' } as const;
      if (!auth.role || typeof auth.role !== 'string' || !isValidRole(auth.role)) return { ok:false, code:401, msg:'Invalid role' } as const;
      if (typeof auth.twofa !== 'boolean') return { ok:false, code:401, msg:'Missing auth fields' } as const;
      if (auth.token.length < 8) return { ok:false, code:401, msg:'Invalid token' } as const;
      return { ok:true, auth } as const;
    };

    const validateMsg = (msg: { type: string; payload?: any }) => {
      if (!['ping','chat','admin','ops','support'].includes(msg.type)) return { ok:false, code:403, msg:'Invalid message type' } as const;
      if (msg.type === 'chat') {
        if (typeof msg.payload !== 'string' || msg.payload.length === 0 || msg.payload.length > MAX_CHAT_LEN) return { ok:false, code:400, msg:'Invalid chat payload' } as const;
      }
      if (msg.type === 'ping' && msg.payload && typeof msg.payload !== 'number') return { ok:false, code:400, msg:'Invalid ping payload' } as const;
      return { ok:true } as const;
    };

    const handlePing = () => { try { server.send(JSON.stringify({ type: 'pong', ts: Date.now() })); } catch {} };
    const broadcastChat = (payload: string) => {
      for (const ws of room) {
        if (ws === server) continue;
        try { ws.send(JSON.stringify({ type: 'chat', payload, context: userContext })); }
        catch { room.delete(ws); }
      }
    };

    const processAuthedMessage = async (raw: string) => {
      const msg = parseJSON<{ type: string; payload?: any }>(raw);
      if (!msg) { sendError(400, 'Malformed message'); return; }
      const v = validateMsg(msg);
      if (!v.ok) { sendError(v.code, v.msg); return; }
      if (msg.type === 'admin' && userContext.role !== 'ROLE_ADMIN') { sendError(403, 'Admin access denied'); return; }
      if (msg.type === 'ops' && userContext.role !== 'ROLE_OPS') { sendError(403, 'Ops access denied'); return; }
      if (msg.type === 'ping') { handlePing(); await setPresence(userContext.userId); return; }
      if (msg.type === 'chat') { broadcastChat(msg.payload as string); return; }
      if (msg.type === 'support' && msg.payload === 'typing') { await setTyping(userContext.userId); return; }
      server.send(JSON.stringify({ type: msg.type, payload: msg.payload, context: userContext }));
    };

    server.addEventListener('message', async (ev: MessageEvent) => {
      // Message-level per-user rate cap (simple KV counting)
      const roomKey = params.roomId || roomId;
      if (!(await handleRateLimit(ip, roomKey))) return;

      const data = ev.data;
      // Reject oversized payloads
      if (isOversized(data)) { sendError(413, 'Payload too large'); return; }
      const raw = String(data || '').trim();
      if (!raw) return;

      // If not authed, expect auth payload
      if (!authed) {
        const res = validateAuth(raw);
        if (!res.ok) { sendError(res.code, res.msg); return; }
        const auth = res.auth;
        authed = true;
        userContext = { userId: String(auth.token ?? '').slice(0,8), role: auth.role, twofa: auth.twofa };
        room.add(server);
        await setPresence(userContext.userId);
        // Welcome message with context
        server.send(JSON.stringify({ type: 'welcome', roomId, connections: room.size, ts: Date.now(), context: userContext }));
        return;
      }

      // After auth, handle messages
      await processAuthedMessage(raw);
    });

    server.addEventListener('close', async () => {
      room.delete(server);
      await clearPresence(userContext.userId);
      await clearTyping(userContext.userId);
    });

    return new Response(null, { status: 101, webSocket: client });
  } catch (e) {
    console.error('WebSocket setup error', e);
    return new Response(JSON.stringify({ success:false, error:'WEBSOCKET_INIT_FAILED', message:String((e as Error).message||'error') }), { status: 500, headers:{'Content-Type':'application/json'} });
  }
};
