// Feed handlers with AI-powered optimization

import type { RouteHandler } from '../types';
import { ApiResponse } from '../types';
// DatabaseService import removed as unused
import { FeedService } from '../services/feed.service';
import { CacheService } from '../services/cache.service';
import { withSpan } from '../utils/otel_wrapper';

// Query DTOs and guards
type FeedQuery = {
  limit: number;
  cursor?: string; // ISO timestamp string for createdAt cursor
};

const parseFeedQuery = (url: URL): FeedQuery => {
  const rawLimit = url.searchParams.get('limit');
  let limit = Number.parseInt(rawLimit ?? '20', 10);
  if (!Number.isFinite(limit)) limit = 20;
  // enforce bounds [5, 50]
  if (limit < 5) limit = 5;
  if (limit > 50) limit = 50;

  const cursor = url.searchParams.get('cursor') || undefined;
  // Basic validation: ISO-like length and allowed chars
  if (cursor && !/^[-:TZ0-9.]+$/.test(cursor)) {
    // reject invalid cursor by ignoring it
    return { limit };
  }
  return { limit, cursor };
};

// Core implementation extracted for instrumentation wrapper
const forYouCore: RouteHandler = async (request, env, _ctx, _params) => {
  try {
    const url = new URL(request.url);
    const { limit, cursor } = parseFeedQuery(url);
    
    // Get userId from auth header if present (optional for feed)
    const authHeader = request.headers.get('Authorization');
    let userId: string | null = null;
    
    if (authHeader?.startsWith('Bearer ')) {
      try {
        const { verifyToken } = await import('../utils/jwt.utils');
        const payload = await verifyToken(authHeader.substring(7), env);
        userId = payload?.userId || null;
      } catch {
        // Ignore auth errors for public feed
      }
    }
    
    const cache = new CacheService(env);
    const feedService = new FeedService(env);
    
    // Try cache first for anonymous users
    if (!userId) {
      const cached = await cache.getFeed(null);
      if (cached) {
        return new Response(
          JSON.stringify({
            success: true,
            data: { videos: cached, cursor: null },
          } as ApiResponse),
          {
            status: 200,
            headers: { 'Content-Type': 'application/json' },
          }
        );
      }
    }
    
    // Get AI-powered personalized feed
    const result = await feedService.getForYouFeed(userId, limit, cursor);
    // Observability: structured log (no PII)
    console.log('[obs.feed.forYou]', JSON.stringify({ ts: Date.now(), authed: !!userId, limit, hasCursor: !!cursor, count: result.videos.length }));
    
    // Cache anonymous feed
    if (!userId && result.videos.length > 0) {
      _ctx?.waitUntil(cache.cacheFeed(null, result.videos));
    }
    
    return new Response(
      JSON.stringify({
        success: true,
        data: result,
      } as ApiResponse),
      {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  } catch (_error) {
    console.error('[obs.feed.forYou.error]', JSON.stringify({ ts: Date.now(), code: 'INTERNAL_ERROR', message: 'Failed to load feed' }));
    return new Response(
      JSON.stringify({
        success: false,
        error: {
          code: 'INTERNAL_ERROR',
          message: 'Failed to load feed',
        },
      } as ApiResponse),
      {
        status: 500,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  }
};

export const forYou: RouteHandler = withSpan(forYouCore, 'feed.forYou');

const followingCore: RouteHandler = async (request, env, _ctx, _params) => {
  try {
    // Following feed requires authentication
    const authHeader = request.headers.get('Authorization');
    if (!authHeader?.startsWith('Bearer ')) {
      return new Response(
        JSON.stringify({
          success: false,
          error: {
            code: 'UNAUTHORIZED',
            message: 'Authentication required',
          },
        } as ApiResponse),
        {
          status: 401,
          headers: { 'Content-Type': 'application/json' },
        }
      );
    }
    
    const { verifyToken } = await import('../utils/jwt.utils');
    const payload = await verifyToken(authHeader.substring(7), env);
    
    if (!payload) {
      return new Response(
        JSON.stringify({
          success: false,
          error: {
            code: 'UNAUTHORIZED',
            message: 'Invalid token',
          },
        } as ApiResponse),
        {
          status: 401,
          headers: { 'Content-Type': 'application/json' },
        }
      );
    }
    
    const url = new URL(request.url);
    const { limit, cursor } = parseFeedQuery(url);
    
    const feedService = new FeedService(env);
    const result = await feedService.getFollowingFeed(payload.userId, limit, cursor ?? undefined);
    // Observability: structured log (no PII)
    console.log('[obs.feed.following]', JSON.stringify({ ts: Date.now(), user: !!payload.userId, limit, hasCursor: !!cursor, count: result.videos.length }));
    
    return new Response(
      JSON.stringify({
        success: true,
        data: result,
      } as ApiResponse),
      {
        status: 200,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  } catch (_error) {
    console.error('[obs.feed.following.error]', JSON.stringify({ ts: Date.now(), code: 'INTERNAL_ERROR', message: 'Failed to load following feed' }));
    return new Response(
      JSON.stringify({
        success: false,
        error: {
          code: 'INTERNAL_ERROR',
          message: 'Failed to load following feed',
        },
      } as ApiResponse),
      {
        status: 500,
        headers: { 'Content-Type': 'application/json' },
      }
    );
  }
};

export const following: RouteHandler = withSpan(followingCore, 'feed.following');
