import {
  loadRegionAgePolicy,
  resolveUserRegion,
  getMinimumAgeForRegion,
  isResidencyRequired,
} from './region_age_policy';

// Region-aware minimum age enforcement
export async function ensureMinimumAgeRegionAware(env: Env, userId: string, userContext: { ip?: string; locale?: string; profileRegion?: string }): Promise<{ allowed: boolean; requiredAge: number; region: string; residencyRequired: boolean; policyName?: string }> {
  const policy = await loadRegionAgePolicy(env);
  const region = resolveUserRegion(userContext);
  const requiredAge = getMinimumAgeForRegion(policy, region);
  const residencyRequired = isResidencyRequired(policy, region);
  const policyName = policy[region]?.policyName;
  // Map requiredAge to ageClass for DB check
  let requiredClass = 'u13';
  if (requiredAge >= 18) requiredClass = 'u18';
  else if (requiredAge >= 16) requiredClass = 'u16';
  // Fallback: treat 13+ as u13, 16+ as u16, 18+ as u18, 21+ as adult
  if (requiredAge >= 21) requiredClass = 'adult';
  const allowed = await ensureMinimumAge(env, userId, requiredClass);
  return { allowed, requiredAge, region, residencyRequired, policyName };
}
import type { Env } from '../types';

export async function ensureMinimumAge(env: Env, userId: string, requiredClass: string): Promise<boolean> {
  try {
    // Prefer canonical schema (userId column). Some legacy schemas used user_id; attempt fallback if first query yields no row.
    let row = await env.DB.prepare('SELECT ageClass, verified FROM age_verification WHERE userId=?1').bind(userId).first();
    if (!row) {
      try { row = await env.DB.prepare('SELECT ageClass, verified FROM age_verification WHERE user_id=?1').bind(userId).first(); } catch { /* ignore */ }
    }
    if (!row) return false;
    const order = ['u13','u16','u18','adult'];
    const idxUser = order.indexOf(String(row.ageClass||''));
    const idxReq = order.indexOf(requiredClass);
    if (idxUser < 0 || idxReq < 0) return false;
    return idxUser >= idxReq && (row.verified === 1 || row.verified === true);
  } catch { return false; }
}

export async function isCountryRestricted(env: Env, countryCode: string): Promise<boolean> {
  try {
    const row = await env.DB.prepare('SELECT active FROM restricted_countries WHERE code=?1').bind(countryCode).first();
    return !!row && row.active === 1;
  } catch { return false; }
}
