import type { RouteHandler } from '../types';
import { instrumentRequest } from './otel';

/**
 * Wrap a RouteHandler with automatic span + latency sample instrumentation.
 * Optionally provide an explicit span name; otherwise derive from request URL.
 */
export function withSpan(handler: RouteHandler, name?: string): RouteHandler {
  return async (request, env, ctx, params) => {
    const spanName = name || `${request.method} ${new URL(request.url).pathname}`;
    return instrumentRequest(env, spanName, () => handler(request, env, ctx, params));
  };
}
